    const nextComps = comps.map((comp) => (comp.id === compId ? { ...comp, included: comp.included === false } : comp));
    setComps(nextComps);
    if (typeof window !== "undefined") {
      window.localStorage.setItem("royalStarComps", JSON.stringify(nextComps));
    }
