source:
import { useEffect, useState } from "react";
import { buildApiUrl } from "../utils/apiClient.js";
import { buildFinancingCostState, getDisplayedFinancingCostValue } from "../utils/financingCostSchema.js";
import { buildUnifiedUnderwritingIntelligence, normalizeDealForIntelligence } from "./intelligenceUpgradeEngine.js";
import logo from "../assets/royal-star-logo.png";
import { getSidebarNavigation, shouldConfirmNavigation } from "../utils/navigationModel.js";
import { useLogoutControl } from "../hooks/useLogoutControl.js";

const API_BASE_URL = "";

const initialFormState = {
  address: "",
  city: "",
  state: "",
  zip: "",
  propertyType: "",
  bedrooms: "",
  bathrooms: "",
  squareFeet: "",
  yearBuilt: "",
  askingPrice: "",
  purchasePrice: "",
  rehabBudget: "",
  arv: "",
  estimatedRent: "",
  taxes: "",
  insurance: "",
  financingCosts: "",
  closingCosts: "",
  actualLoanAmount: "",
  annualInterestRate: "",
  cashToClose: "",
  earnestMoney: "",
  totalInitialCashInvested: "",
  constructionHoldback: "",
  originationFee: "",
  underwritingFee: "",
  servicingFee: "",
  lenderLegalFee: "",
  monitoringFee: "",
  otherLenderFees: "",
  fundedRehab: "",
  paymentType: "",
  holdingMonths: "",
  leadSource: "",
  exitStrategy: "",
  notes: "",
};

const navigation = getSidebarNavigation();

export default function DealIntake({ onBack, dealToEdit, currentView = "dealIntake", onNavigate }) {
  const [formData, setFormData] = useState(initialFormState);
  const [initialSnapshot, setInitialSnapshot] = useState(initialFormState);
  const [statusMessage, setStatusMessage] = useState("");
  const [connectionState, setConnectionState] = useState("Backend Connected");
  const [financingCostDisplay, setFinancingCostDisplay] = useState({
    effectiveFinancingCosts: 0,
    financingCostSource: "calculated",
    rawFinancingCostInput: 0,
    calculatedFinancingCosts: 0,
  });
  const { logoutEnabled, loggingOut, handleLogout, title: logoutTitle } = useLogoutControl(onBack);

  useEffect(() => {
    if (!dealToEdit) {
      setFormData(initialFormState);
      setInitialSnapshot(initialFormState);
      return;
    }

    const underwritingResult = buildUnifiedUnderwritingIntelligence(normalizeDealForIntelligence(dealToEdit), [], []);
    const financingCostState = buildFinancingCostState(dealToEdit, underwritingResult);

    setFinancingCostDisplay({
      effectiveFinancingCosts: financingCostState.effectiveFinancingCosts,
      financingCostSource: financingCostState.financingCostSource,
      rawFinancingCostInput: financingCostState.rawFinancingCostInput,
      calculatedFinancingCosts: financingCostState.calculatedFinancingCosts,
    });

    const hydratedValues = {
      address: dealToEdit.propertyAddress || dealToEdit.address || "",
      city: dealToEdit.city || "",
      state: dealToEdit.state || "",
      zip: dealToEdit.zipCode || dealToEdit.zip || "",
      propertyType: dealToEdit.propertyType || "",
      bedrooms: dealToEdit.bedrooms ?? "",
      bathrooms: dealToEdit.bathrooms ?? "",
      squareFeet: dealToEdit.squareFeet ?? "",
      yearBuilt: dealToEdit.yearBuilt ?? "",
      askingPrice: dealToEdit.askingPrice ?? "",
      purchasePrice: dealToEdit.purchasePrice ?? "",
      rehabBudget: dealToEdit.rehabBudget ?? "",
      arv: dealToEdit.estimatedArv ?? dealToEdit.arv ?? "",
      estimatedRent: dealToEdit.estimatedRent ?? "",
      taxes: dealToEdit.taxes ?? "",
      insurance: dealToEdit.insurance ?? "",
      financingCosts: financingCostState.rawFinancingCostInput ?? "",
      closingCosts: dealToEdit.closingCosts ?? "",
      actualLoanAmount: dealToEdit.actualLoanAmount ?? dealToEdit.loanAmount ?? "",
      annualInterestRate: dealToEdit.annualInterestRate ?? dealToEdit.interestRate ?? "",
      cashToClose: dealToEdit.cashToClose ?? "",
      earnestMoney: dealToEdit.earnestMoney ?? "",
      totalInitialCashInvested: dealToEdit.totalInitialCashInvested ?? dealToEdit.initialCashInvested ?? "",
      constructionHoldback: dealToEdit.constructionHoldback ?? "",
      originationFee: dealToEdit.originationFee ?? "",
      underwritingFee: dealToEdit.underwritingFee ?? "",
      servicingFee: dealToEdit.servicingFee ?? "",
      lenderLegalFee: dealToEdit.lenderLegalFee ?? "",
      monitoringFee: dealToEdit.monitoringFee ?? "",
      otherLenderFees: dealToEdit.otherLenderFees ?? "",
      fundedRehab: dealToEdit.fundedRehab ?? dealToEdit.rehabFunding ?? "",
      paymentType: dealToEdit.paymentType ?? "",
      holdingMonths: dealToEdit.holdingMonths ?? "",
      leadSource: dealToEdit.leadSource || "",
      exitStrategy: dealToEdit.exitStrategy || dealToEdit.strategy || "",
      notes: dealToEdit.notes || "",
    };
    setFormData(hydratedValues);
    setInitialSnapshot(hydratedValues);
  }, [dealToEdit]);

  const handleChange = (event) => {
    const { name, value } = event.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const displayedFinancingCostValue = getDisplayedFinancingCostValue(formData.financingCosts, financingCostDisplay);
  const shouldShowCalculatedFinancingLabel = financingCostDisplay.financingCostSource === "calculated" && Number(formData.financingCosts || 0) <= 0;
  const financingCostDebug = {
    renderedValue: displayedFinancingCostValue,
    stateValue: formData.financingCosts,
    hydratedValue: financingCostDisplay.rawFinancingCostInput,
    repositoryValue: dealToEdit?.financingCosts ?? dealToEdit?.financials?.rawFinancingCostInput ?? 0,
    effectiveFinancingCost: financingCostDisplay.effectiveFinancingCosts,
    financingCostSource: financingCostDisplay.financingCostSource,
  };

  console.log("[DealIntake financing binding]", financingCostDebug);

  const handleClear = () => {
    setFormData(initialFormState);
    setInitialSnapshot(initialFormState);
    setStatusMessage("Form cleared.");
  };

  const hasUnsavedChanges = JSON.stringify(formData) !== JSON.stringify(initialSnapshot);

  const confirmBeforeNavigate = (targetViewKey, fallbackAction) => {
    const mustConfirm = shouldConfirmNavigation({
      hasUnsavedChanges,
      targetViewKey,
      currentViewKey: currentView,
    });

    if (mustConfirm) {
      const proceed = typeof window !== "undefined"
        ? window.confirm("You have unsaved changes. Continue and discard these changes?")
        : true;
      if (!proceed) return;
    }

    if (typeof onNavigate === "function" && targetViewKey) {
      onNavigate(targetViewKey);
      return;
    }

    if (typeof fallbackAction === "function") {
      fallbackAction();
    }
  };

  const handleSubmit = async (event) => {
    event.preventDefault();

    const payload = {
      propertyAddress: formData.address,
      city: formData.city,
      state: formData.state,
      zipCode: formData.zip,
      propertyType: formData.propertyType,
      bedrooms: formData.bedrooms ? Number(formData.bedrooms) : "",
      bathrooms: formData.bathrooms ? Number(formData.bathrooms) : "",
      squareFeet: formData.squareFeet ? Number(formData.squareFeet) : "",
      yearBuilt: formData.yearBuilt ? Number(formData.yearBuilt) : "",
      askingPrice: formData.askingPrice ? Number(formData.askingPrice) : "",
      purchasePrice: formData.purchasePrice ? Number(formData.purchasePrice) : "",
      rehabBudget: formData.rehabBudget ? Number(formData.rehabBudget) : "",
      estimatedArv: formData.arv ? Number(formData.arv) : "",
      estimatedRent: formData.estimatedRent ? Number(formData.estimatedRent) : "",
      taxes: formData.taxes ? Number(formData.taxes) : "",
      insurance: formData.insurance ? Number(formData.insurance) : "",
      financingCosts: formData.financingCosts ? Number(formData.financingCosts) : "",
      financials: {
        rawFinancingCostInput: formData.financingCosts ? Number(formData.financingCosts) : 0,
        calculatedFinancingCosts: 0,
        effectiveFinancingCosts: formData.financingCosts ? Number(formData.financingCosts) : 0,
        financingCostSource: formData.financingCosts ? "manual-override" : "calculated",
      },
      closingCosts: formData.closingCosts ? Number(formData.closingCosts) : "",
      actualLoanAmount: formData.actualLoanAmount ? Number(formData.actualLoanAmount) : "",
      annualInterestRate: formData.annualInterestRate ? Number(formData.annualInterestRate) : "",
      cashToClose: formData.cashToClose ? Number(formData.cashToClose) : "",
      earnestMoney: formData.earnestMoney ? Number(formData.earnestMoney) : "",
      totalInitialCashInvested: formData.totalInitialCashInvested ? Number(formData.totalInitialCashInvested) : "",
      constructionHoldback: formData.constructionHoldback ? Number(formData.constructionHoldback) : "",
      originationFee: formData.originationFee ? Number(formData.originationFee) : "",
      underwritingFee: formData.underwritingFee ? Number(formData.underwritingFee) : "",
      servicingFee: formData.servicingFee ? Number(formData.servicingFee) : "",
      lenderLegalFee: formData.lenderLegalFee ? Number(formData.lenderLegalFee) : "",
      monitoringFee: formData.monitoringFee ? Number(formData.monitoringFee) : "",
      otherLenderFees: formData.otherLenderFees ? Number(formData.otherLenderFees) : "",
      fundedRehab: formData.fundedRehab ? Number(formData.fundedRehab) : "",
      paymentType: formData.paymentType,
      holdingMonths: formData.holdingMonths ? Number(formData.holdingMonths) : "",
      leadSource: formData.leadSource,
      strategy: formData.exitStrategy,
      notes: formData.notes,
    };

    try {
      const endpoint = dealToEdit ? buildApiUrl(`/api/deals/${dealToEdit.id}`) : buildApiUrl("/api/deals");
      const method = dealToEdit ? "PUT" : "POST";
      const response = await fetch(endpoint, {
        method,
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(payload),
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        const message = errorData.errors?.join(" ") || errorData.error || "Validation failed.";
        setConnectionState("Backend Connected");
        setStatusMessage(`Unable to save deal: ${message}`);
        return;
      }

      const savedDeal = await response.json();
      setConnectionState("Backend Connected");
      setStatusMessage(dealToEdit ? "Deal updated successfully." : `Deal saved successfully. ID: ${savedDeal.id}`);
      if (typeof window !== "undefined") {
        window.dispatchEvent(new Event("royalStarDealsUpdated"));
      }
      setFormData(initialFormState);
      setInitialSnapshot(initialFormState);
    } catch (error) {
      console.error("Unable to save deal:", error);
      setConnectionState("Local Fallback");

      try {
        const existingDeals = JSON.parse(
          window.localStorage.getItem("royalStarDeals") || "[]"
        );

        const dealToSave = {
          id: dealToEdit ? dealToEdit.id : Date.now(),
          propertyAddress: formData.address,
          address: formData.address,
          city: formData.city,
          state: formData.state,
          zip: formData.zip,
          zipCode: formData.zip,
          propertyType: formData.propertyType,
          bedrooms: formData.bedrooms ? Number(formData.bedrooms) : "",
          bathrooms: formData.bathrooms ? Number(formData.bathrooms) : "",
          squareFeet: formData.squareFeet ? Number(formData.squareFeet) : "",
          yearBuilt: formData.yearBuilt ? Number(formData.yearBuilt) : "",
          askingPrice: formData.askingPrice ? Number(formData.askingPrice) : "",
          purchasePrice: formData.purchasePrice ? Number(formData.purchasePrice) : "",
          rehabBudget: formData.rehabBudget ? Number(formData.rehabBudget) : "",
          estimatedArv: formData.arv ? Number(formData.arv) : "",
          arv: formData.arv ? Number(formData.arv) : "",
          projectedARV: formData.arv ? Number(formData.arv) : "",
          estimatedRent: formData.estimatedRent ? Number(formData.estimatedRent) : "",
          taxes: formData.taxes ? Number(formData.taxes) : "",
          insurance: formData.insurance ? Number(formData.insurance) : "",
          financingCosts: formData.financingCosts ? Number(formData.financingCosts) : "",
          financials: {
            rawFinancingCostInput: formData.financingCosts ? Number(formData.financingCosts) : 0,
            calculatedFinancingCosts: 0,
            effectiveFinancingCosts: formData.financingCosts ? Number(formData.financingCosts) : 0,
            financingCostSource: formData.financingCosts ? "manual-override" : "calculated",
          },
          closingCosts: formData.closingCosts ? Number(formData.closingCosts) : "",
          actualLoanAmount: formData.actualLoanAmount ? Number(formData.actualLoanAmount) : "",
          annualInterestRate: formData.annualInterestRate ? Number(formData.annualInterestRate) : "",
          cashToClose: formData.cashToClose ? Number(formData.cashToClose) : "",
          earnestMoney: formData.earnestMoney ? Number(formData.earnestMoney) : "",
          totalInitialCashInvested: formData.totalInitialCashInvested ? Number(formData.totalInitialCashInvested) : "",
          constructionHoldback: formData.constructionHoldback ? Number(formData.constructionHoldback) : "",
          originationFee: formData.originationFee ? Number(formData.originationFee) : "",
          underwritingFee: formData.underwritingFee ? Number(formData.underwritingFee) : "",
          servicingFee: formData.servicingFee ? Number(formData.servicingFee) : "",
          lenderLegalFee: formData.lenderLegalFee ? Number(formData.lenderLegalFee) : "",
          monitoringFee: formData.monitoringFee ? Number(formData.monitoringFee) : "",
          otherLenderFees: formData.otherLenderFees ? Number(formData.otherLenderFees) : "",
          fundedRehab: formData.fundedRehab ? Number(formData.fundedRehab) : "",
          paymentType: formData.paymentType,
          holdingMonths: formData.holdingMonths ? Number(formData.holdingMonths) : "",
          leadSource: formData.leadSource,
          strategy: formData.exitStrategy,
          exitStrategy: formData.exitStrategy,
          notes: formData.notes,
          createdAt: dealToEdit?.createdAt || new Date().toISOString(),
          updatedAt: new Date().toISOString(),
        };

        const updatedDeals = dealToEdit
          ? existingDeals.map((entry) => (String(entry.id) === String(dealToEdit.id) ? dealToSave : entry))
          : [...existingDeals, dealToSave];

        window.localStorage.setItem("royalStarDeals", JSON.stringify(updatedDeals));
        if (typeof window !== "undefined") {
          window.dispatchEvent(new Event("royalStarDealsUpdated"));
        }
        setStatusMessage(dealToEdit ? "Deal updated successfully." : `Deal saved locally. Total deals: ${updatedDeals.length}.`);
        setFormData(initialFormState);
        setInitialSnapshot(initialFormState);
      } catch (fallbackError) {
        console.error("Unable to save deal locally:", fallbackError);
        setStatusMessage("Unable to save deal. Please try again.");
      }
    }
  };

  return (
    <div style={styles.page}>
      <aside style={styles.sidebar}>
        <div style={styles.logoArea}>
          <img src={logo} alt="Royal Star Properties" style={styles.logo} />
        </div>

        <nav style={styles.nav}>
          {navigation.map((item) => (
            <button
              key={item.id}
              type="button"
              style={styles.navButton}
              aria-current={item.viewKey === currentView ? "page" : undefined}
              onClick={() => confirmBeforeNavigate(item.viewKey)}
            >
              <span style={styles.navIcon}>{item.icon}</span>
              <span>{item.label}</span>
              <span style={styles.navTab} />
            </button>
          ))}

          <button
            type="button"
            style={{ ...styles.logout, ...(logoutEnabled ? {} : styles.logoutDisabled) }}
            onClick={handleLogout}
            disabled={!logoutEnabled || loggingOut}
            aria-disabled={!logoutEnabled || loggingOut}
            title={logoutTitle}
            aria-label={logoutEnabled ? "Log out" : "Log out unavailable while authentication is inactive"}
          >
            <span style={styles.navIcon}>↪</span>
            <span>LOG OUT</span>
          </button>
        </nav>

        <div style={styles.smallMark}>RS★</div>
      </aside>

      <main style={styles.main}>
        <section style={styles.topBar}>
          <button type="button" style={styles.backButton} onClick={() => confirmBeforeNavigate("dashboard", onBack)}>
            ◀ COMMAND CENTER
          </button>

          <div style={styles.headingBlock}>
            <h1 style={styles.company}>ROYAL STAR PROPERTIES, LLC</h1>
            <p style={styles.subtitle}>DEAL INTAKE / OPPORTUNITY ENTRY</p>
          </div>

          <div style={styles.adminBadge}>👤 BRANDON STERLING</div>
        </section>

        <section style={styles.card}>
          <div style={styles.cardHeader}>
            <div>
              <h2 style={styles.cardTitle}>{dealToEdit ? "EDIT DEAL" : "NEW DEAL INTAKE"}</h2>
              <p style={styles.cardSubtitle}>
                Capture the property details, numbers, and strategy for every opportunity.
              </p>
            </div>
            <div style={styles.statusBox}>
              <div>{statusMessage || "Ready to capture a new deal."}</div>
              <div style={styles.connectionBadge}>{connectionState}</div>
            </div>
          </div>

          <form onSubmit={handleSubmit} style={styles.form}>
            <Section title="PROPERTY INFORMATION">
              <div style={styles.gridTwo}>
                <Field label="Address" name="address" value={formData.address} onChange={handleChange} />
                <Field label="City" name="city" value={formData.city} onChange={handleChange} />
                <Field label="State" name="state" value={formData.state} onChange={handleChange} />
                <Field label="ZIP" name="zip" value={formData.zip} onChange={handleChange} />
                <Field label="Property Type" name="propertyType" value={formData.propertyType} onChange={handleChange} />
                <Field label="Bedrooms" name="bedrooms" value={formData.bedrooms} onChange={handleChange} type="number" />
                <Field label="Bathrooms" name="bathrooms" value={formData.bathrooms} onChange={handleChange} type="number" />
                <Field label="Square Feet" name="squareFeet" value={formData.squareFeet} onChange={handleChange} type="number" />
                <Field label="Year Built" name="yearBuilt" value={formData.yearBuilt} onChange={handleChange} type="number" />
              </div>
            </Section>

            <Section title="DEAL NUMBERS">
              <div style={styles.gridTwo}>
                <Field label="Asking Price" name="askingPrice" value={formData.askingPrice} onChange={handleChange} type="number" />
                <Field label="Purchase Price" name="purchasePrice" value={formData.purchasePrice} onChange={handleChange} type="number" />
                <Field label="Rehab Budget" name="rehabBudget" value={formData.rehabBudget} onChange={handleChange} type="number" />
                <Field label="ARV" name="arv" value={formData.arv} onChange={handleChange} type="number" />
                <Field label="Estimated Rent" name="estimatedRent" value={formData.estimatedRent} onChange={handleChange} type="number" />
                <Field label="Taxes" name="taxes" value={formData.taxes} onChange={handleChange} type="number" />
                <Field label="Insurance" name="insurance" value={formData.insurance} onChange={handleChange} type="number" />
                <div>
                  <Field
                    label={shouldShowCalculatedFinancingLabel ? "Calculated Financing Costs" : "Financing Costs"}
                    name="financingCosts"
                    value={displayedFinancingCostValue}
                    onChange={handleChange}
                    type="number"
                  />
                  <div style={styles.helperText}>
                    {financingCostDisplay.financingCostSource === "calculated"
                      ? "Showing the effective financing cost. Enter a manual override to replace it."
                      : "Enter a manual override to replace the calculated financing cost."}
                  </div>
                  {financingCostDisplay.effectiveFinancingCosts > 0 && (
                    <div style={styles.helperTextSecondary}>
                      Effective Financing Costs: ${Number(financingCostDisplay.effectiveFinancingCosts).toLocaleString("en-US", { maximumFractionDigits: 2 })}
                    </div>
                  )}
                </div>
                <Field label="Closing Costs" name="closingCosts" value={formData.closingCosts} onChange={handleChange} type="number" />
                <Field label="Actual Loan Amount" name="actualLoanAmount" value={formData.actualLoanAmount} onChange={handleChange} type="number" />
                <Field label="Annual Interest Rate" name="annualInterestRate" value={formData.annualInterestRate} onChange={handleChange} type="number" />
                <Field label="Cash to Close" name="cashToClose" value={formData.cashToClose} onChange={handleChange} type="number" />
