    dealIntelligence: [],
    rehabProjects: [],
    lenders: [],
    contractors: [],
    portfolioIntelligence,
  }), [normalizedPortfolio, portfolioIntelligence]);

  const refinanceExitOptimizer = useMemo(() => buildRefinanceExitOptimizer({
    properties: normalizedPortfolio,
    deals: [],
    portfolioIntelligence,
    capitalAllocationEngine,
