      status,
      startedAt,
      completedAt,
      durationMs,
      diagnostics: {
        ...stage.diagnostics,
        source: 'Enterprise Automation Orchestrator',
        detail: status === 'Completed' ? `${stage.name} completed successfully` : `${stage.name} is waiting for source data`,
