function buildConfidenceLevel(score) {
  if (score >= 80) return 'High';
  if (score >= 65) return 'Moderate';
  if (score >= 50) return 'Low';
  return 'Insufficient Data';
}

export function buildExecutiveStrategyOptimizationEngine(payload = {}) {
  const deal = normalizeObject(payload.deal);
  const analysis = normalizeObject(payload.analysis);
  const portfolioIntelligence = normalizeObject(payload.portfolioIntelligence);
  const executiveRecommendationEngine = normalizeObject(payload.executiveRecommendationEngine);
  const executiveActionQueue = normalizeObject(payload.executiveActionQueue);
  const capitalAllocationEngine = normalizeObject(payload.capitalAllocationEngine);
  const marketAnalysis = normalizeObject(payload.marketAnalysis);
  const forecastAnalysis = normalizeObject(payload.forecastAnalysis);

  const reserveShortfall = safeNumber(portfolioIntelligence.summary?.reserveShortfallValue);
  const availableLiquidity = safeNumber(portfolioIntelligence.summary?.availableLiquidity);
  const cashRequired = safeNumber(analysis.cashRequired);
  const balanceScore = safeNumber(portfolioIntelligence.portfolioBalancingEngine?.portfolioBalanceScore);
  const diversification = safeNumber(portfolioIntelligence.portfolioBalancingEngine?.diversificationScore);
  const liquidityRatio = safeNumber(portfolioIntelligence.portfolioBalancingEngine?.liquidityReserveRatio);
  const riskScore = safeNumber(analysis.overallRisk);
  const forecastConfidence = safeNumber(forecastAnalysis.forecastConfidence);
  const marketStability = safeNumber(marketAnalysis.marketRiskEngine?.marketStabilityScore);
  const recommendationScore = safeNumber(executiveRecommendationEngine?.recommendations?.[0]?.priorityScore);
  const confidenceScore = clamp(Math.round((recommendationScore * 0.4) + (forecastConfidence * 0.25) + (marketStability * 0.2) + (balanceScore * 0.15)), 0, 100);
  const expectedRoi = safeNumber(analysis.roi);
  const liquidityRemaining = Math.max(0, availableLiquidity - cashRequired);
  const annualCashFlow = Math.max(0, safeNumber(analysis.estimatedFlipProfit ?? analysis.projectedProfit) * 0.12);
  const equityGrowth = Math.max(0, safeNumber(analysis.estimatedFlipProfit ?? analysis.projectedProfit) * 0.8);
  const capitalEfficiency = clamp(Math.round((safeNumber(analysis.estimatedFlipProfit ?? analysis.projectedProfit) / Math.max(cashRequired, 1)) * 10), 0, 100);

  const baseSignals = {
    expectedRoi,
    cashRequired,
    liquidityRemaining,
    diversification,
    riskScore,
    confidenceScore,
    annualCashFlow,
    equityGrowth,
    capitalEfficiency,
  };

  const strategyScores = strategyDefinitions.map((strategy) => {
    const score = buildStrategyScore(strategy, {
      ...baseSignals,
      expectedRoi: strategy.key === 'Cash Preservation' ? Math.max(0, expectedRoi * 0.8) : strategy.key === 'Conservative Growth' ? expectedRoi * 0.9 : strategy.key === 'Aggressive Growth' ? expectedRoi * 1.15 : expectedRoi,
      cashRequired: strategy.key === 'Cash Preservation' ? Math.max(0, cashRequired * 0.65) : strategy.key === 'Conservative Growth' ? Math.max(0, cashRequired * 0.85) : strategy.key === 'Aggressive Growth' ? cashRequired * 1.1 : cashRequired,
      liquidityRemaining: strategy.key === 'Cash Preservation' ? Math.max(liquidityRemaining, availableLiquidity) : strategy.key === 'Conservative Growth' ? Math.max(liquidityRemaining, availableLiquidity * 0.8) : liquidityRemaining,
      diversification: strategy.key === 'Mixed Strategy' ? Math.min(100, diversification + 8) : strategy.key === 'BRRRR Focus' ? Math.min(100, diversification + 4) : strategy.key === 'Flip Focus' ? Math.max(0, diversification - 4) : diversification,
      riskScore: strategy.key === 'Aggressive Growth' ? Math.min(100, riskScore + 8) : strategy.key === 'Cash Preservation' ? Math.max(0, riskScore - 8) : strategy.key === 'Conservative Growth' ? Math.max(0, riskScore - 4) : riskScore,
      confidenceScore: strategy.key === 'Balanced Growth' ? Math.min(100, confidenceScore + 3) : strategy.key === 'Conservative Growth' ? Math.min(100, confidenceScore + 2) : confidenceScore,
      annualCashFlow: strategy.key === 'BRRRR Focus' ? annualCashFlow * 1.08 : strategy.key === 'Cash Preservation' ? annualCashFlow * 0.8 : annualCashFlow,
      equityGrowth: strategy.key === 'Aggressive Growth' ? equityGrowth * 1.1 : strategy.key === 'Balanced Growth' ? equityGrowth * 1.05 : strategy.key === 'Conservative Growth' ? equityGrowth * 0.9 : equityGrowth,
      capitalEfficiency: strategy.key === 'Cash Preservation' ? Math.min(100, capitalEfficiency + 6) : strategy.key === 'Balanced Growth' ? Math.min(100, capitalEfficiency + 3) : capitalEfficiency,
    });

    return {
      strategyName: strategy.key,
      score,
      confidenceLevel: buildConfidenceLevel(score),
      reasoning: buildReasoning(strategy, score, baseSignals),
      tradeOffs: buildTradeOffs(strategy, baseSignals),
      expectedRoi: Number((expectedRoi * (strategy.key === 'Aggressive Growth' ? 1.1 : strategy.key === 'Conservative Growth' ? 0.9 : strategy.key === 'Cash Preservation' ? 0.8 : 1)).toFixed(3)),
      cashRequired: Math.round(cashRequired * (strategy.key === 'Cash Preservation' ? 0.65 : strategy.key === 'Conservative Growth' ? 0.85 : strategy.key === 'Aggressive Growth' ? 1.1 : strategy.key === 'BRRRR Focus' ? 0.95 : 1)),
      liquidityRemaining: Math.round(liquidityRemaining * (strategy.key === 'Cash Preservation' ? 1.08 : strategy.key === 'Conservative Growth' ? 0.95 : strategy.key === 'Aggressive Growth' ? 0.9 : 1)),
      portfolioDiversification: Math.round(diversification + (strategy.key === 'Mixed Strategy' ? 8 : strategy.key === 'BRRRR Focus' ? 4 : strategy.key === 'Flip Focus' ? -3 : 0)),
      riskScore: Math.round(riskScore + (strategy.key === 'Aggressive Growth' ? 8 : strategy.key === 'Cash Preservation' ? -8 : strategy.key === 'Conservative Growth' ? -4 : 0)),
      confidenceScore: Math.round(confidenceScore + (strategy.key === 'Balanced Growth' ? 3 : strategy.key === 'Conservative Growth' ? 2 : 0)),
      annualCashFlow: Math.round(annualCashFlow * (strategy.key === 'BRRRR Focus' ? 1.08 : strategy.key === 'Cash Preservation' ? 0.8 : 1)),
      equityGrowth: Math.round(equityGrowth * (strategy.key === 'Aggressive Growth' ? 1.1 : strategy.key === 'Balanced Growth' ? 1.05 : strategy.key === 'Conservative Growth' ? 0.9 : 1)),
      capitalEfficiency: Math.round(capitalEfficiency + (strategy.key === 'Cash Preservation' ? 6 : strategy.key === 'Balanced Growth' ? 3 : 0)),
    };
  }).sort((left, right) => right.score - left.score);

  const manualOverrideStrategy = safeString(payload.manualOverrideStrategy || payload.manualOverride || '', '');
  const manualOverrideApplied = Boolean(manualOverrideStrategy);
  const selectedStrategy = manualOverrideApplied
    ? strategyScores.find((entry) => entry.strategyName === manualOverrideStrategy) || strategyScores[0]
    : strategyScores[0];

  const improvement = selectedStrategy?.score > 0 ? Math.round(selectedStrategy.score - 50) : 0;

  return {
    recommendedStrategy: selectedStrategy?.strategyName || 'Balanced Growth',
    reasoningSummary: selectedStrategy?.reasoning || 'Balanced Growth remains the most resilient option based on current conditions.',
    tradeOffs: selectedStrategy?.tradeOffs || [],
    confidenceLevel: selectedStrategy?.confidenceLevel || 'Insufficient Data',
    expectedImprovementOverCurrentAllocation: `${improvement > 0 ? '+' : ''}${improvement}%`,
    strategyScores,
    selectedStrategy: {
      ...selectedStrategy,
      score: selectedStrategy?.score || 0,
    },
    summary: {
      totalStrategies: strategyScores.length,
      topScore: strategyScores[0]?.score || 0,
      lowestScore: strategyScores[strategyScores.length - 1]?.score || 0,
      selectedStrategyName: selectedStrategy?.strategyName || 'Balanced Growth',
    },
    manualOverrideSummary: {
      applied: manualOverrideApplied,
      strategyName: manualOverrideApplied ? manualOverrideStrategy : null,
    },
  };
}

export function safeNumber(value) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
}

export function safeDisplay(value, fallback = "Insufficient Data") {
  if (value === null || value === undefined || value === "" || Number.isNaN(value)) return fallback;
  if (typeof value === "number" && !Number.isFinite(value)) return fallback;
  return value;
}

function sanitize(value) {
  return safeDisplay(value, "Insufficient Data");
}

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function calculateEligibility(funding, lender, deal) {
  const failures = [];
  const maxLtc = safeNumber(lender.maximumLTC ?? lender.maximumLoanToCost);
  const maxLtv = safeNumber(lender.maximumPurchaseLTV ?? lender.maximumLTV ?? lender.maximumARVLTV);
  const maxLtarv = safeNumber(lender.maximumARVLTV ?? lender.maximumLTARV ?? lender.maximumARV);
  const requiredCash = safeNumber(lender.requiredCashContribution ?? lender.liquidityRequirement);
  const requiredDscr = safeNumber(lender.DSCRMinimum ?? lender.minimumDSCR);
  const minCredit = safeNumber(lender.creditScoreMinimum);
  const loanAmount = funding.loanAmount;
  const purchasePrice = safeNumber(deal.purchasePrice ?? deal.askingPrice);
  const rehabBudget = safeNumber(deal.rehabBudget);
  const arv = safeNumber(deal.estimatedArv ?? deal.arv ?? deal.projectedARV ?? deal.currentValue);
  const totalCost = purchasePrice + rehabBudget + safeNumber(deal.closingCosts) + safeNumber(deal.financingCosts) + safeNumber(deal.taxes) + safeNumber(deal.insurance);
  const ltc = totalCost > 0 ? loanAmount / totalCost : 0;
  const ltv = purchasePrice > 0 ? loanAmount / purchasePrice : 0;
  const ltarv = arv > 0 ? loanAmount / arv : 0;
  const dscr = safeNumber(deal.estimatedRent) > 0 && funding.monthlyPrincipalAndInterest > 0 ? safeNumber(deal.estimatedRent) / funding.monthlyPrincipalAndInterest : 0;

  if (maxLtc > 0 && ltc > maxLtc) failures.push(`LTC exceeds ${Math.round(maxLtc * 100)}%`);
  if (maxLtv > 0 && ltv > maxLtv) failures.push(`LTV exceeds ${Math.round(maxLtv * 100)}%`);
  if (maxLtarv > 0 && ltarv > maxLtarv) failures.push(`LTARV exceeds ${Math.round(maxLtarv * 100)}%`);
  if (maxLtc > 0 && loanAmount > safeNumber(lender.maximumLoanAmount)) failures.push("Loan amount exceeds lender maximum");
  if (requiredCash > 0 && funding.cashRequired > requiredCash) failures.push("Cash contribution exceeds lender requirement");
  if (requiredDscr > 0 && dscr < requiredDscr) failures.push(`DSCR below ${requiredDscr}`);
  if (minCredit > 0 && safeNumber(deal.creditScore) > 0 && safeNumber(deal.creditScore) < minCredit) failures.push(`Credit score below ${minCredit}`);
  if (safeNumber(deal.cashOnHand) > 0 && funding.cashRequired > safeNumber(deal.cashOnHand)) failures.push("Cash requirement exceeds available liquidity");

  if (failures.length === 0) {
    return { status: "Qualified", failures };
  }

  if (failures.length <= 2) {
    return { status: "Conditionally Qualified", failures };
  }

  return { status: "Not Qualified", failures };
}

function calculateWarnings(funding, lender, deal) {
  const warnings = [];
  const rate = safeNumber(lender.interestRate);
  const points = safeNumber(lender.originationPoints);
  const fees = funding.originationFees;
  const purchasePrice = safeNumber(deal.purchasePrice ?? deal.askingPrice);
  const rehabBudget = safeNumber(deal.rehabBudget);
  const arv = safeNumber(deal.estimatedArv ?? deal.arv ?? deal.projectedARV ?? deal.currentValue);
  const totalCost = purchasePrice + rehabBudget + safeNumber(deal.closingCosts) + safeNumber(deal.financingCosts) + safeNumber(deal.taxes) + safeNumber(deal.insurance);
  const ltc = totalCost > 0 ? funding.loanAmount / totalCost : 0;
  const ltarv = arv > 0 ? funding.loanAmount / arv : 0;
  const dscr = safeNumber(deal.estimatedRent) > 0 && funding.monthlyPrincipalAndInterest > 0 ? safeNumber(deal.estimatedRent) / funding.monthlyPrincipalAndInterest : 0;

  if (rate > 0.12) warnings.push("Excessive Interest Rate");
  if (points > 0.03) warnings.push("High Points");
  if (fees > 5000) warnings.push("High Fees");
  if (ltc > 0.8) warnings.push("LTC Exceeded");
  if (ltarv > 0.75) warnings.push("LTARV Exceeded");
  if (dscr > 0 && dscr < 1.25) warnings.push("Low DSCR");
  if (funding.loanAmount > 0 && purchasePrice > 0 && funding.loanAmount > purchasePrice * 0.8) warnings.push("Loan Amount Too Large");
  if (funding.cashRequired > 25000) warnings.push("Cash Requirement Too High");
  if (safeNumber(lender.loanTermMonths) > 0 && safeNumber(lender.loanTermMonths) < 12) warnings.push("Short Loan Term");
  if (safeNumber(lender.loanTermMonths) > 0 && safeNumber(lender.loanTermMonths) < 24) warnings.push("Maturity Risk");

  return warnings;
}

function calculateFinancingScore(funding, lender, deal) {
  const rate = safeNumber(lender.interestRate);
  const points = safeNumber(lender.originationPoints);
  const fees = funding.originationFees;
  const cashRequired = funding.cashRequired;
  const purchasePrice = safeNumber(deal.purchasePrice ?? deal.askingPrice);
  const rehabBudget = safeNumber(deal.rehabBudget);
  const arv = safeNumber(deal.estimatedArv ?? deal.arv ?? deal.projectedARV ?? deal.currentValue);
  const totalCost = purchasePrice + rehabBudget + safeNumber(deal.closingCosts) + safeNumber(deal.financingCosts) + safeNumber(deal.taxes) + safeNumber(deal.insurance);
  const ltc = totalCost > 0 ? funding.loanAmount / totalCost : 0;
  const ltarv = arv > 0 ? funding.loanAmount / arv : 0;
  const monthlyPayment = funding.monthlyPrincipalAndInterest;
  const dscr = safeNumber(deal.estimatedRent) > 0 && monthlyPayment > 0 ? safeNumber(deal.estimatedRent) / monthlyPayment : 0;
  const closingSpeed = safeNumber(lender.drawTurnaroundDays);
  const flexibility = safeNumber(lender.flexibilityScore);

  let score = 100;
  if (rate > 0.1) score -= 10;
  if (points > 0.02) score -= 6;
  if (fees > 5000) score -= 5;
  if (cashRequired > 20000) score -= 8;
  if (ltc > 0.75) score -= 8;
  if (ltarv > 0.7) score -= 7;
  if (monthlyPayment > 4000) score -= 6;
  if (dscr > 0 && dscr < 1.25) score -= 8;
  if (closingSpeed > 7) score -= 4;
  if (flexibility > 0 && flexibility < 7) score -= 5;
  score = clamp(Math.round(score), 0, 100);
  return score;
}

function calculateRiskLevel(warnings) {
  const severity = ["Low", "Moderate", "High", "Critical"];
  if (warnings.includes("Critical") || warnings.length >= 5) return severity[3];
  if (warnings.length >= 3) return severity[2];
  if (warnings.length >= 1) return severity[1];
  return severity[0];
}

export function buildLenderComparison(deal = {}, lenders = []) {
  const normalized = (lenders || []).filter(Boolean);
  if (normalized.length <= 1) return null;
  const evaluations = normalized.map((lender) => ({
    lender,
    financing: buildFinancingIntelligence(deal, lender),
  }));
  const qualified = evaluations.filter((entry) => entry.financing.qualifyingStatus === "Qualified");
  const ranked = qualified.length > 0 ? qualified : evaluations;
  ranked.sort((left, right) => {
    if (right.financing.financingScore !== left.financing.financingScore) {
      return right.financing.financingScore - left.financing.financingScore;
    }
    if (left.financing.monthlyPrincipalAndInterest !== right.financing.monthlyPrincipalAndInterest) {
      return left.financing.monthlyPrincipalAndInterest - right.financing.monthlyPrincipalAndInterest;
    }
    return left.financing.cashRequired - right.financing.cashRequired;
  });
  const best = ranked[0];
  return {
    lenderCount: normalized.length,
    bestLender: best?.lender || null,
    bestFinancing: best?.financing || null,
  };
}

export function buildFinancingIntelligence(deal = {}, lender = {}) {
  const purchasePrice = safeNumber(deal.purchasePrice ?? deal.askingPrice);
  const rehabBudget = safeNumber(deal.rehabBudget);
  const closingCosts = safeNumber(deal.closingCosts);
  const financingCosts = safeNumber(deal.financingCosts);
  const taxes = safeNumber(deal.taxes);
  const insurance = safeNumber(deal.insurance);
  const arv = safeNumber(deal.estimatedArv ?? deal.arv ?? deal.projectedARV ?? deal.currentValue);
  const estimatedRent = safeNumber(deal.estimatedRent ?? deal.marketRent ?? deal.projectedRent);
  const interestRate = safeNumber(lender.interestRate);
  const points = safeNumber(lender.originationPoints);
  const originationFees = safeNumber(lender.underwritingFee) + safeNumber(lender.processingFee) + safeNumber(lender.appraisalFee) + safeNumber(lender.legalFee) + safeNumber(lender.drawFee) + safeNumber(lender.extensionFee);
  const totalProjectCost = purchasePrice + rehabBudget + closingCosts + financingCosts + taxes + insurance;
  const maxLoanAmount = safeNumber(lender.maximumLoanAmount);
  const minimumLoanAmount = safeNumber(lender.minimumLoanAmount);
  const baseLoanAmount = totalProjectCost > 0 ? totalProjectCost * 0.8 : 0;
  const loanAmount = maxLoanAmount > 0 ? Math.min(baseLoanAmount, maxLoanAmount) : baseLoanAmount;
  const cashRequired = Math.max(0, totalProjectCost - loanAmount);
  const pointsCost = loanAmount * points;
  const totalFinancingCost = pointsCost + originationFees;
  const monthlyInterestPayment = loanAmount > 0 ? (loanAmount * interestRate) / 12 : 0;
  const monthlyPrincipalAndInterest = loanAmount > 0 ? (loanAmount / 12) + monthlyInterestPayment : 0;
  const ltc = totalProjectCost > 0 ? loanAmount / totalProjectCost : 0;
  const ltv = purchasePrice > 0 ? loanAmount / purchasePrice : 0;
  const ltarv = arv > 0 ? loanAmount / arv : 0;
  const dscr = estimatedRent > 0 && monthlyPrincipalAndInterest > 0 ? estimatedRent / monthlyPrincipalAndInterest : 0;
  const interestCarryDuringRehab = monthlyInterestPayment * 6;
  const totalInterestExpense = monthlyInterestPayment * 12;
  const estimatedCashToClose = cashRequired + totalFinancingCost + closingCosts + financingCosts + taxes + insurance;
  const remainingLiquidityAfterClosing = safeNumber(deal.cashOnHand) - estimatedCashToClose;

  const funding = {
    loanAmount: Math.max(0, loanAmount),
    cashRequired: Math.max(0, cashRequired),
    pointsCost,
    originationFees,
    totalFinancingCost,
    monthlyInterestPayment,
    monthlyPrincipalAndInterest,
    ltc,
    ltv,
    ltarv,
    dscr,
    interestCarryDuringRehab,
    totalInterestExpense,
    estimatedCashToClose,
    remainingLiquidityAfterClosing,
  };

  const qualification = calculateEligibility(funding, lender, deal);
  const financingWarnings = calculateWarnings(funding, lender, deal);
  const financingScore = calculateFinancingScore(funding, lender, deal);
  const riskLevel = calculateRiskLevel(financingWarnings);

  return {
    ...funding,
    lenderId: lender.id || "",
    selectedLender: lender.lenderName || lender.loanProgramName || "Insufficient Data",
    loanProgram: lender.loanProgramName || lender.loanType || "Insufficient Data",
    loanType: lender.loanType || lender.loanProgramName || "Insufficient Data",
    interestRate,
    points,
    fees: originationFees,
    minimumLoanAmount,
    maximumLoanAmount: maxLoanAmount,
    minimumLoanAmount,
    maximumLtc: safeNumber(lender.maximumLTC ?? lender.maximumLoanToCost),
    maximumLtv: safeNumber(lender.maximumPurchaseLTV ?? lender.maximumLTV ?? lender.maximumARVLTV),
    maximumLtarv: safeNumber(lender.maximumARVLTV ?? lender.maximumLTARV ?? lender.maximumARV),
    requiredCashContribution: safeNumber(lender.requiredCashContribution ?? lender.liquidityRequirement),
    drawSchedule: lender.drawScheduleType || lender.drawSchedule || "Insufficient Data",
    loanTerm: safeNumber(lender.loanTermMonths),
    extensionOptions: lender.extensionOptions || "Insufficient Data",
    minimumCreditScore: safeNumber(lender.creditScoreMinimum),
    minimumDscr: safeNumber(lender.DSCRMinimum ?? lender.minimumDSCR),
    closingTime: lender.drawTurnaroundDays || "Insufficient Data",
    notes: lender.notes || "Insufficient Data",
    ltc,
    ltv,
    ltarv,
    dscr,
    financingScore,
    financingGrade: financingScore >= 85 ? "A" : financingScore >= 70 ? "B" : financingScore >= 55 ? "C" : financingScore >= 40 ? "D" : "F",
    financingExplanation: financingScore >= 80 ? "Strong overall financing profile." : financingScore >= 60 ? "Moderate financing profile with some tradeoffs." : "Financing is expensive or restrictive.",
    qualifyingStatus: qualification.status,
    qualificationFailures: qualification.failures,
    financingWarnings,
    financingRisk: riskLevel,
    activeWarnings: financingWarnings.join(" • ") || "No active warnings",
    displayValue: sanitize,
  };
}

