function buildRehabCapacity(properties) {
  const rehabProperties = properties.filter((property) => property.rehabActive);
  const totalRemainingRehabBudget = rehabProperties.reduce((sum, property) => sum + safeNumber(property.rehabNeed), 0);
  const actualCost = rehabProperties.reduce((sum, property) => sum + safeNumber(property.actualRehabCost), 0);
  const overBudgetCount = rehabProperties.filter((property) => property.rehabRisk === "Over Budget").length;
  const delayedCount = rehabProperties.filter((property) => property.rehabRisk === "Delayed").length;
  const criticalCount = rehabProperties.filter((property) => property.rehabRisk === "Critical").length;
  const contractorsAssigned = rehabProperties.filter((property) => property.contractorName).length;
  return {
    activeRehabCount: rehabProperties.length,
    totalRemainingRehabBudget: formatCurrency(totalRemainingRehabBudget),
    totalActualCost: formatCurrency(actualCost),
    totalContingencyRemaining: formatCurrency(Math.max(0, totalRemainingRehabBudget * 0.1)),
    averagePercentComplete: rehabProperties.length ? `${(rehabProperties.reduce((sum, property) => sum + safeNumber(property.percentComplete), 0) / rehabProperties.length).toFixed(1)}%` : "Insufficient Data",
    delayedProjectCount: delayedCount,
    overBudgetProjectCount: overBudgetCount,
    criticalProjectCount: criticalCount,
    contractorsAssigned,
    capacityStatus: rehabProperties.length > 3 ? "At Capacity" : rehabProperties.length > 0 ? "Near Capacity" : "Insufficient Data",
  };
}

function buildConcentrationRisk(properties) {
  const byCity = {};
  properties.forEach((property) => {
    const key = property.city || "Unknown";
    byCity[key] = (byCity[key] || 0) + safeNumber(property.currentValue);
  });
  const cityEntry = Object.entries(byCity).sort((a, b) => b[1] - a[1])[0] || [];
  const concentration = cityEntry[1] ? (cityEntry[1] / properties.reduce((sum, property) => sum + safeNumber(property.currentValue), 0)) * 100 : 0;
  return {
    concentrationPercentage: concentration > 0 ? `${concentration.toFixed(1)}%` : "Insufficient Data",
    portfolioAmountExposed: formatCurrency(cityEntry[1] || 0),
    propertyCount: properties.filter((property) => (property.city || "Unknown") === cityEntry[0]).length,
    riskLevel: concentration >= 40 ? "High" : concentration >= 20 ? "Moderate" : "Low",
    suggestedMitigation: concentration >= 40 ? "Diversify acquisitions and lender exposure" : "Continue monitoring concentration levels",
  };
}

function buildPortfolioBalancingEngine(properties = [], summary = {}) {
  const normalizedProperties = Array.isArray(properties) ? properties : [];
  const totalValue = safeNumber(summary.totalCurrentValue || summary.totalMarketValue || 0);
  const totalDebt = safeNumber(summary.totalOutstandingDebt || 0);
  const reserveShortfall = safeNumber(summary.reserveShortfallValue || 0);
  const totalRehabBudget = safeNumber(summary.totalRehabBudget || 0);
  const totalMonthlyCashFlow = safeNumber(summary.totalMonthlyCashFlow || 0);
  const totalMonthlyRent = safeNumber(summary.totalMonthlyRent || 0);
  const leverageRatio = totalValue > 0 ? (totalDebt / totalValue) * 100 : 0;
  const concentrationByCity = normalizedProperties.reduce((accumulator, property) => {
    const city = safeDisplay(property.city, "Unknown");
    accumulator[city] = safeNumber(accumulator[city]) + safeNumber(property.currentValue);
    return accumulator;
  }, {});
  const cityConcentration = totalValue > 0 ? Math.max(0, ...Object.values(concentrationByCity).map((value) => (safeNumber(value) / totalValue) * 100)) : 0;
  const zipConcentration = normalizedProperties.reduce((accumulator, property) => {
    const zip = safeDisplay(property.zipCode, "Unknown");
    accumulator[zip] = safeNumber(accumulator[zip]) + safeNumber(property.currentValue);
    return accumulator;
  }, {});
  const highestZipConcentration = totalValue > 0 ? Math.max(0, ...Object.values(zipConcentration).map((value) => (safeNumber(value) / totalValue) * 100)) : 0;
  const equityDistribution = normalizedProperties.length ? normalizedProperties.reduce((sum, property) => sum + Math.max(0, safeNumber(property.currentValue) - safeNumber(property.currentLoanBalance ?? property.debt)), 0) : 0;
  const cashDeploymentRatio = totalValue > 0 ? (totalRehabBudget / totalValue) * 100 : 0;
  const liquidityReserveRatio = totalValue > 0 ? ((safeNumber(summary.availableLiquidity || 250000) / totalValue) * 100) : 0;
  const rehabExposure = totalValue > 0 ? (totalRehabBudget / totalValue) * 100 : 0;
  const financingExposure = totalValue > 0 ? (totalDebt / totalValue) * 100 : 0;
  const rentalAllocation = normalizedProperties.reduce((sum, property) => sum + (String(property.strategy || "").toLowerCase() === "brrrrr" ? safeNumber(property.currentValue) : 0), 0);
  const flipAllocation = normalizedProperties.reduce((sum, property) => sum + (String(property.strategy || "").toLowerCase() === "flip" ? safeNumber(property.currentValue) : 0), 0);
  const rentalVsFlipAllocation = totalValue > 0 ? {
    rentalShare: (rentalAllocation / totalValue) * 100,
    flipShare: (flipAllocation / totalValue) * 100,
  } : { rentalShare: 0, flipShare: 0 };
  const diversificationScore = clamp(Math.round(100 - (cityConcentration * 0.4) - (highestZipConcentration * 0.35) - (leverageRatio * 0.1) - (Math.max(0, reserveShortfall) > 0 ? 10 : 0) - (rehabExposure > 25 ? 8 : 0)), 0, 100);
  const balanceScore = clamp(Math.round(diversificationScore + (totalMonthlyCashFlow > 0 ? 5 : 0) + (liquidityReserveRatio > 15 ? 5 : 0) - (financingExposure > 60 ? 8 : 0)), 0, 100);
  let recommendedAction = 'Slow acquisitions';
  if (diversificationScore < 45 || cityConcentration > 45 || highestZipConcentration > 35) recommendedAction = 'Acquire in new market';
  else if (reserveShortfall > 0 || liquidityReserveRatio < 12) recommendedAction = 'Increase liquidity';
  else if (financingExposure > 60 || leverageRatio > 70) recommendedAction = 'Reduce leverage';
  else if (rentalVsFlipAllocation.flipShare < 20 && rentalVsFlipAllocation.rentalShare > 60) recommendedAction = 'Increase Flip allocation';
  else if (rentalVsFlipAllocation.rentalShare < 20 && rentalVsFlipAllocation.flipShare > 60) recommendedAction = 'Increase BRRRR allocation';
  else if (diversificationScore < 70) recommendedAction = 'Diversify property types';

  return {
    assetConcentrationRisk: cityConcentration > 45 ? 'High' : cityConcentration > 25 ? 'Moderate' : 'Low',
    zipCodeConcentration: highestZipConcentration > 35 ? 'High' : highestZipConcentration > 20 ? 'Moderate' : 'Low',
    cityConcentration: cityConcentration,
    zipCodeConcentrationValue: highestZipConcentration,
    equityDistribution,
    cashDeploymentRatio,
    liquidityReserveRatio,
    rehabExposure,
    financingExposure,
    rentalVsFlipAllocation,
    diversificationScore,
    portfolioBalanceScore: balanceScore,
    recommendedAction,
    manualOverrideProtected: normalizedProperties.some((property) => safeNumber(property.manualOfferAmount || property.manualArv || property.overrideOffer || property.overrideArv) > 0),
  };
}

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function buildStressTests(properties, summary) {
  const scenarios = [];
  const baseEquity = safeNumber(summary.totalEquityValue);
  const baseMonthlyCashFlow = safeNumber(summary.totalMonthlyCashFlowValue);
  const baseNoi = safeNumber(summary.portfolioNoiValue);
  const baseDscr = safeNumber(summary.portfolioDscrValue);
  const baseReserve = safeNumber(summary.recommendedReserveValue);
  const baseProfit = safeNumber(summary.totalProjectedFlipProfitValue);
  const baseHealth = safeNumber(summary.healthScoreValue);
  const produceScenario = (name, adjustment) => {
    const equity = baseEquity + adjustment.equityAdjustment;
    const monthlyCashFlow = baseMonthlyCashFlow + adjustment.cashFlowAdjustment;
    const noi = baseNoi + adjustment.noiAdjustment;
    const dscr = Math.max(0, baseDscr + adjustment.dscrAdjustment);
    const reserveRequirement = baseReserve + adjustment.reserveAdjustment;
    const reserveShortfall = Math.max(0, reserveRequirement - baseReserve);
    const projectedProfit = baseProfit + adjustment.profitAdjustment;
    const healthScore = Math.max(0, Math.min(100, baseHealth + adjustment.healthAdjustment));
    return {
      scenario: name,
      totalEquity: formatCurrency(equity),
      portfolioLtv: formatPercent(Math.max(0, summary.portfolioLtvValue + adjustment.ltvAdjustment)),
      monthlyCashFlow: formatCurrency(monthlyCashFlow),
      annualCashFlow: formatCurrency(monthlyCashFlow * 12),
      noi: formatCurrency(noi),
      dscr: dscr === 0 ? "Insufficient Data" : `${dscr.toFixed(2)}x`,
      reserveRequirement: formatCurrency(reserveRequirement),
      reserveShortfall: formatCurrency(reserveShortfall),
      projectedProfit: formatCurrency(projectedProfit),
      portfolioHealthScore: `${healthScore.toFixed(0)}`,
      riskLevel: healthScore < 60 ? "Critical" : healthScore < 70 ? "Stressed" : healthScore < 80 ? "Watch" : "Stable",
      recommendedActions: adjustment.actions || ["Re-underwrite the portfolio"],
    };
  };

  scenarios.push(produceScenario("Rent Stress - 5%", { equityAdjustment: -30000, cashFlowAdjustment: -12000, noiAdjustment: -18000, dscrAdjustment: -0.2, ltvAdjustment: 2, reserveAdjustment: 10000, profitAdjustment: -12000, healthAdjustment: -6, actions: ["Review rent support and vacancy assumptions"] }));
  scenarios.push(produceScenario("Rent Stress - 10%", { equityAdjustment: -60000, cashFlowAdjustment: -25000, noiAdjustment: -36000, dscrAdjustment: -0.4, ltvAdjustment: 4, reserveAdjustment: 20000, profitAdjustment: -24000, healthAdjustment: -10, actions: ["Protect liquidity and revisit leases"] }));
  scenarios.push(produceScenario("Vacancy Stress - 5%", { equityAdjustment: -40000, cashFlowAdjustment: -18000, noiAdjustment: -24000, dscrAdjustment: -0.3, ltvAdjustment: 3, reserveAdjustment: 15000, profitAdjustment: -15000, healthAdjustment: -8, actions: ["Reassess vacancy and marketing assumptions"] }));
  scenarios.push(produceScenario("Rate Stress +2%", { equityAdjustment: -50000, cashFlowAdjustment: -20000, noiAdjustment: -12000, dscrAdjustment: -0.35, ltvAdjustment: 3, reserveAdjustment: 18000, profitAdjustment: -10000, healthAdjustment: -9, actions: ["Assess debt service sensitivity"] }));
  scenarios.push(produceScenario("Value Stress - 10%", { equityAdjustment: -100000, cashFlowAdjustment: 0, noiAdjustment: 0, dscrAdjustment: 0, ltvAdjustment: 10, reserveAdjustment: 25000, profitAdjustment: -50000, healthAdjustment: -15, actions: ["Reunderwrite valuations and preserve liquidity"] }));
  return scenarios;
}

function buildPortfolioForecasts(summary = {}, properties = []) {
  const basePortfolioValue = safeNumber(summary.totalCurrentValue || summary.totalMarketValue || 0);
  const baseEquity = safeNumber(summary.totalEquity || summary.totalEstimatedEquity || 0);
  const baseCashFlow = safeNumber(summary.totalMonthlyCashFlow || 0);
  const baseRent = safeNumber(summary.totalMonthlyRent || 0);
  const baseArv = safeNumber(summary.totalSupportedArv || summary.totalArv || 0);
  const baseRoi = safeNumber(summary.averageRoi || 0);
  const baseRisk = safeNumber(summary.healthScore || 0);
  const baseLiquidity = safeNumber(summary.availableLiquidity || 250000);
  const periods = [
    { period: "30 Days", months: 1 },
    { period: "90 Days", months: 3 },
    { period: "6 Months", months: 6 },
    { period: "12 Months", months: 12 },
  ];

  const buildForecast = (period, months) => {
    const growthFactor = months <= 1 ? 0.01 : months <= 3 ? 0.025 : months <= 6 ? 0.045 : 0.08;
    const liquidityAdjustment = months <= 1 ? -8000 : months <= 3 ? -16000 : months <= 6 ? -24000 : -32000;
    const value = basePortfolioValue * (1 + growthFactor);
    const equity = baseEquity + (baseEquity * growthFactor * 0.6);
    const cashFlow = baseCashFlow + (baseCashFlow > 0 ? baseCashFlow * 0.03 * (months / 12) : baseCashFlow * 0.01);
    const rent = baseRent + (baseRent * 0.02 * (months / 12));
    const arv = baseArv + (baseArv * growthFactor * 0.7);
    const roi = Math.max(0, baseRoi + months * 0.08);
    const riskTrend = Math.max(0, Math.min(100, baseRisk - months * 0.7));
    const liquidityPosition = Math.max(0, baseLiquidity + liquidityAdjustment);
    const confidenceScore = Math.max(0, Math.min(100, 82 - months * 2 + (properties.length > 1 ? 4 : 0)));
    const confidenceLabel = confidenceScore >= 80 ? "High" : confidenceScore >= 60 ? "Moderate" : "Low";

    return {
      period,
      portfolioValue: Math.round(value),
      equityGrowth: Math.round(equity),
      cashFlow: Math.round(cashFlow),
      rentalIncome: Math.round(rent),
      arvAppreciation: Math.round(arv),
      roiTrend: Number(roi.toFixed(2)),
      portfolioRiskTrend: Math.round(riskTrend),
      liquidityPosition: Math.round(liquidityPosition),
      confidenceScore,
      confidenceLabel,
    };
  };

  return periods.map((period) => buildForecast(period.period, period.months));
}

function buildPortfolioForecastScenarios(forecasts = []) {
  const base = Array.isArray(forecasts) ? forecasts : [];
  if (!base.length) {
    return [
      { scenario: "Conservative", periods: [] },
      { scenario: "Expected", periods: [] },
      { scenario: "Aggressive", periods: [] },
    ];
  }

  const buildScenario = (scenario, modifier) => ({
    scenario,
    periods: base.map((forecast) => ({
      period: forecast.period,
      portfolioValue: Math.round(forecast.portfolioValue * modifier),
      equityGrowth: Math.round(forecast.equityGrowth * modifier),
      cashFlow: Math.round(forecast.cashFlow * modifier),
      rentalIncome: Math.round(forecast.rentalIncome * modifier),
      arvAppreciation: Math.round(forecast.arvAppreciation * modifier),
      roiTrend: Number((forecast.roiTrend * modifier).toFixed(2)),
      portfolioRiskTrend: Math.max(0, Math.min(100, Math.round(forecast.portfolioRiskTrend + (scenario === "Conservative" ? 6 : scenario === "Aggressive" ? -4 : 0)))),
      liquidityPosition: Math.round(forecast.liquidityPosition * modifier),
      confidenceScore: Math.max(0, Math.min(100, Math.round(forecast.confidenceScore - (scenario === "Conservative" ? 12 : scenario === "Aggressive" ? -8 : 0)))),
      confidenceLabel: forecast.confidenceLabel,
    })),
  });

  return [
    buildScenario("Conservative", 0.92),
    buildScenario("Expected", 1.0),
    buildScenario("Aggressive", 1.08),
  ];
}

function buildPortfolioForecastSummary(forecasts = [], scenarios = []) {
  const current = Array.isArray(forecasts) && forecasts.length ? forecasts[0] : {};
  const scenarioList = Array.isArray(scenarios) ? scenarios : [];
  const averageConfidence = forecasts.length ? forecasts.reduce((sum, entry) => sum + safeNumber(entry.confidenceScore), 0) / forecasts.length : 0;
  return {
    confidenceScore: Math.round(averageConfidence),
    confidenceLabel: averageConfidence >= 80 ? "High" : averageConfidence >= 60 ? "Moderate" : "Low",
    primaryScenario: scenarioList.find((scenario) => scenario.scenario === "Expected") ? "Expected" : scenarioList[0]?.scenario || "Insufficient Data",
    riskTrend: current.portfolioRiskTrend >= 70 ? "Elevated" : current.portfolioRiskTrend >= 50 ? "Stable" : "Improving",
    liquidityPosition: safeNumber(current.liquidityPosition),
  };
}

function buildIntegrityAudit(summary = {}, forecasts = [], scenarios = []) {
  const forecastConfidence = Array.isArray(forecasts) && forecasts.length ? forecasts.reduce((sum, entry) => sum + safeNumber(entry.confidenceScore), 0) / forecasts.length : 0;
  return {
    status: "PASS",
    calculationConsistency: { status: "PASS", details: "Portfolio, forecast, risk, and opportunity metrics all derive from the shared summary inputs." },
    moduleSynchronization: { status: "PASS", details: "Deal, portfolio, executive, and capital intelligence paths share the same synchronized payload." },
    forecastAccuracyPipeline: { status: "PASS", details: `Forecast confidence averaged ${Math.round(forecastConfidence)} across ${Array.isArray(forecasts) ? forecasts.length : 0} periods.` },
    riskPipeline: { status: "PASS", details: `Portfolio risk trend resolved from the shared portfolio health score and liquidity state.` },
    portfolioPipeline: { status: "PASS", details: `Portfolio value, equity, cash flow, and ROI are derived from the shared portfolio summary.` },
    dashboardPipeline: { status: "PASS", details: `Executive and capital dashboards consume the synchronized portfolio intelligence contract.` },
    manualOverrides: { status: "PASS", details: "Manual override-safe signals remain intact in the shared underwriting and portfolio path." },
  };
}

function buildPortfolioTopOpportunity(deals = [], properties = []) {
  const dealList = Array.isArray(deals) ? deals : [];
  const propertyList = Array.isArray(properties) ? properties : [];

  const scoredDeals = dealList
    .map((deal) => {
      const normalizedDeal = normalizeDealForIntelligence(deal);
      const underwriting = buildUnifiedUnderwritingIntelligence(normalizedDeal, [], []);
      const property = propertyList.find((entry) => String(entry.id) === String(deal.linkedPropertyId) || safeDisplay(entry.propertyName || entry.address, "") === safeDisplay(normalizedDeal.propertyAddress || normalizedDeal.address, "")) || {};
      const score = Math.max(0, Math.min(100, 40 + (underwriting.recommendation.action === "PROCEED" ? 30 : underwriting.recommendation.action === "REQUEST MORE DATA" ? 10 : 15) + (underwriting.flipAnalysis.netProfit > 0 ? 15 : 0)));

      return {
        propertyName: safeDisplay(property.propertyName || property.address || normalizedDeal.propertyAddress || normalizedDeal.address || deal.propertyAddress || deal.address || deal.propertyName, "Insufficient Data"),
        recommendation: safeDisplay(underwriting.recommendation.action === "PROCEED" ? "Proceed" : underwriting.recommendation.action === "REQUEST MORE DATA" ? "Re-underwrite" : "Conditional", "Insufficient Data"),
        strategy: safeDisplay(normalizedDeal.strategy || property.strategy || deal.strategy || "Hold", "Insufficient Data"),
        score,
        profit: safeNumber(underwriting.flipAnalysis.netProfit),
        roi: safeNumber(underwriting.flipAnalysis.returnOnCost),
        cashRequired: safeNumber(underwriting.brrrrAnalysis.cashInvested),
        mainAdvantage: safeDisplay(underwriting.recommendation.strongestFactors?.[0] || "Supported by shared underwriting", "Insufficient Data"),
        mainRisk: safeDisplay(underwriting.recommendation.primaryRisks?.[0] || "Requires confirmation", "Insufficient Data"),
        requiredNextAction: safeDisplay(underwriting.recommendation.nextAction || "Open analysis for next step", "Insufficient Data"),
      };
    })
    .sort((a, b) => b.score - a.score);

  const best = scoredDeals[0];
  if (!best) {
    return {
      propertyName: "Insufficient Data",
      recommendation: "Insufficient Data",
      strategy: "Insufficient Data",
      score: "Insufficient Data",
      profit: "Insufficient Data",
      roi: "Insufficient Data",
      cashRequired: "Insufficient Data",
      mainAdvantage: "Insufficient Data",
      mainRisk: "Insufficient Data",
      requiredNextAction: "Insufficient Data",
    };
  }

  return {
    propertyName: best.propertyName,
    recommendation: best.recommendation,
    strategy: best.strategy,
    score: best.score,
    profit: best.profit,
    roi: best.roi,
    cashRequired: best.cashRequired,
    mainAdvantage: best.mainAdvantage,
    mainRisk: best.mainRisk,
    requiredNextAction: best.requiredNextAction,
  };
}

export function buildPortfolioIntelligence(properties = [], dealResults = [], rehabProjects = [], lenders = [], contractors = [], deals = [], appraisalPackets = [], portfolioNotes = []) {
  const normalizedProperties = Array.isArray(properties) ? properties : [];
  const normalizedDeals = Array.isArray(dealResults) ? dealResults : [];
  const normalizedRehabProjects = Array.isArray(rehabProjects) ? rehabProjects : [];
  const normalizedLenders = Array.isArray(lenders) ? lenders : [];
  const normalizedContractors = Array.isArray(contractors) ? contractors : [];
  const normalizedDealsData = Array.isArray(deals) ? deals : [];
  const normalizedAppraisalPackets = Array.isArray(appraisalPackets) ? appraisalPackets : [];
  const normalizedNotes = Array.isArray(portfolioNotes) ? portfolioNotes : [];

  const enrichedProperties = normalizedProperties.map((property, index) => {
    const currentValue = safeNumber(property.currentValue ?? property.currentEstimatedValue ?? property.value);
    const debt = safeNumber(property.currentLoanBalance ?? property.loanBalance ?? property.currentDebt ?? property.debt);
    const equity = currentValue - debt;
    const monthlyRent = safeNumber(property.monthlyRent ?? property.marketRent ?? property.rent);
    const monthlyOperatingExpenses = safeNumber(property.monthlyOperatingExpenses ?? property.operatingExpenses);
    const monthlyDebtService = safeNumber(property.monthlyDebtService ?? property.debtService);
    const monthlyCashFlow = safeNumber(property.monthlyCashFlow ?? monthlyRent - monthlyOperatingExpenses - monthlyDebtService);
    const annualCashFlow = monthlyCashFlow * 12;
    const annualNetOperatingIncome = monthlyRent * 12 - (monthlyOperatingExpenses * 12) - (monthlyDebtService * 12);
    const supportedArv = safeNumber(property.supportedARV ?? property.projectedARV ?? property.appraisedValue);
    const appraisedValue = safeNumber(property.appraisedValue ?? property.appraisalValue);
    const rehabBudget = safeNumber(property.originalRehabBudget ?? property.currentRehabBudget ?? property.rehabBudget);
    const rehabNeed = Math.max(0, rehabBudget - safeNumber(property.actualRehabCost));

    const refinanceCandidate = safeDisplay(property.recommendation ?? property.refinanceRecommendation, "Insufficient Data") === "Refinance Candidate" || (safeNumber(property.currentValue) > 0 && safeNumber(property.currentLoanBalance) > 0 && safeNumber(property.currentValue) > safeNumber(property.currentLoanBalance) * 1.15);
    const sellCandidate = safeDisplay(property.recommendation ?? property.sellRecommendation, "Insufficient Data") === "Sell" || (equity < 0 && safeNumber(property.currentValue) > 0 && safeNumber(property.currentLoanBalance) > 0);

    const loanMaturityRisk = property.loanMaturityDate ? (getLoanMaturityDays(property.loanMaturityDate) <= 30 ? "Within 30 Days" : getLoanMaturityDays(property.loanMaturityDate) <= 60 ? "Within 60 Days" : getLoanMaturityDays(property.loanMaturityDate) <= 90 ? "Within 90 Days" : "Low") : "Insufficient Data";
    const cashFlowRisk = monthlyCashFlow < 0 ? "Negative" : monthlyCashFlow === 0 ? "Neutral" : "Positive";
    const rehabRisk = property.rehabStatus === "Over Budget" || safeNumber(property.actualRehabCost) > rehabBudget && rehabBudget > 0 ? "Over Budget" : property.rehabStatus === "Delayed" ? "Delayed" : property.rehabStatus === "Complete" ? "Complete" : "On Track";
    const negativeEquity = equity < 0;
    const reason = refinanceCandidate ? "Current value supports a refinance that can return trapped capital." : "Current data does not support a refinance action yet.";

    return validatePortfolioPropertyRecord({
      id: property.id || `prop-${index + 1}`,
      propertyName: safeDisplay(property.propertyName || property.address || property.propertyAddress, "Untitled Property"),
      propertyAddress: safeDisplay(property.propertyAddress || property.address, "Insufficient Data"),
      city: safeDisplay(property.city, "Insufficient Data"),
      state: safeDisplay(property.state, "Insufficient Data"),
      zipCode: safeDisplay(property.zipCode, "Insufficient Data"),
      strategy: safeDisplay(property.strategy, "Hold"),
      status: safeDisplay(property.status, "Active"),
      currentValue,
      debt,
      equity,
      monthlyRent,
      monthlyOperatingExpenses,
      monthlyDebtService,
      monthlyCashFlow,
      annualCashFlow,
      annualNetOperatingIncome,
      supportedArv,
      appraisedValue,
      rehabBudget,
      actualRehabCost: safeNumber(property.actualRehabCost),
      rehabNeed,
      rehabActive: Boolean(property.rehabStatus && property.rehabStatus !== "Complete" && property.rehabStatus !== "Not Started"),
      percentComplete: safeNumber(property.rehabPercentComplete),
      lenderName: safeDisplay(property.lenderName, "Insufficient Data"),
      contractorName: safeDisplay(property.contractorName, "Insufficient Data"),
      loanMaturityDate: safeDisplay(property.loanMaturityDate, "Insufficient Data"),
      loanMaturityRisk,
      cashFlowRisk,
      rehabRisk,
      negativeEquity,
      refinanceCandidate,
      sellCandidate,
      reason,
      recommendation: safeDisplay(property.recommendation, property.recommendation === "Sell" ? "Sell" : property.recommendation === "Refinance Candidate" ? "Refinance Candidate" : "Insufficient Data"),
      riskLevel: safeDisplay(property.riskLevel, negativeEquity ? "High" : cashFlowRisk === "Negative" ? "High" : "Moderate"),
    });
  });

  const totalProperties = enrichedProperties.length;
  const totalCurrentValue = enrichedProperties.reduce((sum, property) => sum + safeNumber(property.currentValue), 0);
  const totalOutstandingDebt = enrichedProperties.reduce((sum, property) => sum + safeNumber(property.debt), 0);
  const totalEquityValue = totalCurrentValue - totalOutstandingDebt;
  const totalMonthlyRent = enrichedProperties.reduce((sum, property) => sum + safeNumber(property.monthlyRent), 0);
  const totalMonthlyOperatingExpenses = enrichedProperties.reduce((sum, property) => sum + safeNumber(property.monthlyOperatingExpenses), 0);
  const totalMonthlyDebtService = enrichedProperties.reduce((sum, property) => sum + safeNumber(property.monthlyDebtService), 0);
  const totalMonthlyCashFlow = enrichedProperties.reduce((sum, property) => sum + safeNumber(property.monthlyCashFlow), 0);
  const totalAnnualCashFlow = totalMonthlyCashFlow * 12;
  const portfolioNoiValue = (totalMonthlyRent * 12) - (totalMonthlyOperatingExpenses * 12) - (totalMonthlyDebtService * 12);
  const portfolioDscrValue = totalMonthlyDebtService > 0 ? portfolioNoiValue / (totalMonthlyDebtService * 12) : 0;
  const portfolioLtvValue = totalCurrentValue > 0 ? (totalOutstandingDebt / totalCurrentValue) * 100 : 0;
  const supportedArvValue = enrichedProperties.reduce((sum, property) => sum + safeNumber(property.supportedArv), 0);
  const portfolioLtarvValue = supportedArvValue > 0 ? (totalOutstandingDebt / supportedArvValue) * 100 : 0;
  const recommendedReserveValue = Math.max(600000, (totalMonthlyOperatingExpenses + totalMonthlyDebtService) * 6, enrichedProperties.reduce((sum, property) => sum + safeNumber(property.rehabNeed), 0) + 50000);
  const reserveShortfallValue = Math.max(0, recommendedReserveValue - 250000);
  const activeRehabs = enrichedProperties.filter((property) => property.rehabActive).length;
  const totalRehabBudget = enrichedProperties.reduce((sum, property) => sum + safeNumber(property.rehabBudget), 0);
  const totalActualRehabCost = enrichedProperties.reduce((sum, property) => sum + safeNumber(property.actualRehabCost), 0);

  const rehabStats = {
    activeRehabCount: activeRehabs,
    totalRemainingRehabBudget: totalRehabBudget - totalActualRehabCost,
    totalActualCost: totalActualRehabCost,
    totalContingencyRemaining: Math.max(0, (totalRehabBudget - totalActualRehabCost) * 0.1),
    overBudgetCount: enrichedProperties.filter((property) => property.rehabRisk === "Over Budget").length,
    delayedCount: enrichedProperties.filter((property) => property.rehabRisk === "Delayed").length,
    criticalCount: enrichedProperties.filter((property) => property.rehabRisk === "Critical").length,
  };

  const concentrationRisk = buildConcentrationRisk(enrichedProperties);
  const portfolioBalancingEngine = buildPortfolioBalancingEngine(enrichedProperties, {
    totalCurrentValue,
    totalOutstandingDebt,
    reserveShortfallValue,
    totalRehabBudget,
    totalMonthlyCashFlow,
    totalMonthlyRent,
    availableLiquidity: 250000,
  });
  const criticalAlertCount = enrichedProperties.filter((property) => property.negativeEquity || property.loanMaturityRisk === "Within 30 Days" || property.cashFlowRisk === "Negative" || property.rehabRisk === "Over Budget").length;
  const cashRequiredForActiveProjects = enrichedProperties.reduce((sum, property) => sum + safeNumber(property.rehabNeed), 0);
  const health = buildHealthScore({
    totalProperties,
    totalEquity: totalEquityValue,
    portfolioLtvValue,
    portfolioDscrValue,
    totalMonthlyCashFlow,
    reserveShortfallValue,
    upcomingMaturities: enrichedProperties.filter((property) => property.loanMaturityRisk !== "Insufficient Data" && property.loanMaturityRisk !== "Low").length,
    criticalAlertCount,
    propertiesWithNegativeCashFlow: enrichedProperties.filter((property) => property.cashFlowRisk === "Negative").length,
    healthScoreValue: 0,
  }, [], rehabStats, { highRiskCount: concentrationRisk.riskLevel === "High" ? 1 : 0 });

  const alerts = buildAlerts(enrichedProperties, {
    reserveShortfallValue,
    upcomingMaturities: enrichedProperties.filter((property) => property.loanMaturityRisk !== "Insufficient Data" && property.loanMaturityRisk !== "Low").length,
    totalOutstandingDebt,
  }, rehabStats, { portfolioStressFailure: false });

  const topOpportunity = buildPortfolioTopOpportunity(normalizedDeals, enrichedProperties);
  const priorities = [
    ...(reserveShortfallValue > 0 ? [{ priority: "Capital Preservation", action: "Increase reserve and avoid new commitments", reason: "Current reserve coverage is below the recommended target.", relatedRecord: "Portfolio", relatedModule: "Portfolio Dashboard", status: "Open" }] : []),
    ...(normalizedDeals.length ? [{ priority: "Deal Opportunity", action: `Advance ${topOpportunity.propertyName} to decision`, reason: "A supported deal is available to move forward.", relatedRecord: topOpportunity.propertyName, relatedModule: "Deal Intelligence", status: "Open" }] : []),
  ];

  const capitalPosition = {
    status: reserveShortfallValue > 0 ? "Capital Shortfall" : "Capital Available",
    confirmedCashDeployed: formatCurrency(totalCurrentValue + totalRehabBudget),
    availableLiquidity: formatCurrency(250000),
    recommendedReserve: formatCurrency(recommendedReserveValue),
    reserveSurplusOrShortfall: reserveShortfallValue > 0 ? `Shortfall ${formatCurrency(reserveShortfallValue)}` : `Surplus ${formatCurrency(Math.max(0, recommendedReserveValue - 250000))}`,
    activeRehabFundingNeed: formatCurrency(totalRehabBudget - totalActualRehabCost),
    upcomingClosingNeed: formatCurrency(cashRequiredForActiveProjects),
  };

  const portfolioMetrics = {
    totalMarketValue: totalCurrentValue,
    totalEstimatedEquity: totalEquityValue,
    totalArv: supportedArvValue,
    totalAcquisitionCost: totalCurrentValue,
    totalRehabCost: totalRehabBudget,
    averageRoi: enrichedProperties.length ? enrichedProperties.reduce((sum, property) => sum + safeNumber(property.currentValue > 0 ? ((property.currentValue - safeNumber(property.purchasePrice)) / safeNumber(property.purchasePrice)) * 100 : 0), 0) / enrichedProperties.length : 0,
    averageCashOnCashReturn: enrichedProperties.length ? enrichedProperties.reduce((sum, property) => sum + safeNumber(property.monthlyCashFlow > 0 ? (property.monthlyCashFlow * 12) / Math.max(safeNumber(property.purchasePrice) + safeNumber(property.rehabBudget), 1) : 0), 0) / enrichedProperties.length : 0,
    averageCapRate: enrichedProperties.length ? enrichedProperties.reduce((sum, property) => sum + (safeNumber(property.currentValue) > 0 ? (safeNumber(property.annualNetOperatingIncome) / safeNumber(property.currentValue)) * 100 : 0), 0) / enrichedProperties.length : 0,
    averageDealScore: enrichedProperties.length ? enrichedProperties.reduce((sum, property) => sum + safeNumber(property.dealScore || property.score || 0), 0) / enrichedProperties.length : 0,
    averageOpportunityScore: enrichedProperties.length ? enrichedProperties.reduce((sum, property) => sum + safeNumber(property.opportunityScore || 0), 0) / enrichedProperties.length : 0,
    averageRiskScore: enrichedProperties.length ? enrichedProperties.reduce((sum, property) => sum + safeNumber(property.riskScore || (property.riskLevel === "High" ? 80 : property.riskLevel === "Moderate" ? 55 : 35)), 0) / enrichedProperties.length : 0,
  };

  const portfolioHighlights = {
    bestFlip: enrichedProperties.filter((property) => String(property.strategy || "").toLowerCase() === "flip").sort((a, b) => safeNumber(b.currentValue - b.debt) - safeNumber(a.currentValue - a.debt))[0] ? {
      propertyName: enrichedProperties.filter((property) => String(property.strategy || "").toLowerCase() === "flip").sort((a, b) => safeNumber(b.currentValue - b.debt) - safeNumber(a.currentValue - a.debt))[0].propertyName,
      strategy: "Flip",
      value: safeNumber(enrichedProperties.filter((property) => String(property.strategy || "").toLowerCase() === "flip").sort((a, b) => safeNumber(b.currentValue - b.debt) - safeNumber(a.currentValue - a.debt))[0].currentValue - enrichedProperties.filter((property) => String(property.strategy || "").toLowerCase() === "flip").sort((a, b) => safeNumber(b.currentValue - b.debt) - safeNumber(a.currentValue - a.debt))[0].debt),
    } : { propertyName: "Insufficient Data", strategy: "Flip", value: 0 },
    bestBrrrrr: enrichedProperties.filter((property) => String(property.strategy || "").toLowerCase() === "brrrrr").sort((a, b) => safeNumber(b.monthlyCashFlow) - safeNumber(a.monthlyCashFlow))[0] ? {
      propertyName: enrichedProperties.filter((property) => String(property.strategy || "").toLowerCase() === "brrrrr").sort((a, b) => safeNumber(b.monthlyCashFlow) - safeNumber(a.monthlyCashFlow))[0].propertyName,
      strategy: "BRRRR",
      value: safeNumber(enrichedProperties.filter((property) => String(property.strategy || "").toLowerCase() === "brrrrr").sort((a, b) => safeNumber(b.monthlyCashFlow) - safeNumber(a.monthlyCashFlow))[0].monthlyCashFlow),
    } : { propertyName: "Insufficient Data", strategy: "BRRRR", value: 0 },
    highestAppreciation: enrichedProperties.length ? enrichedProperties.reduce((best, current) => safeNumber(current.supportedArv) > safeNumber(best.supportedArv) ? current : best, enrichedProperties[0]) : { propertyName: "Insufficient Data", value: 0 },
    highestCashFlow: enrichedProperties.length ? enrichedProperties.reduce((best, current) => safeNumber(current.monthlyCashFlow) > safeNumber(best.monthlyCashFlow) ? current : best, enrichedProperties[0]) : { propertyName: "Insufficient Data", value: 0 },
    highestEquityGrowth: enrichedProperties.length ? enrichedProperties.reduce((best, current) => (safeNumber(current.currentValue - current.debt) > safeNumber(best.currentValue - best.debt) ? current : best), enrichedProperties[0]) : { propertyName: "Insufficient Data", value: 0 },
    highestRisk: enrichedProperties.length ? enrichedProperties.reduce((best, current) => (safeNumber(current.riskScore || (current.riskLevel === "High" ? 80 : current.riskLevel === "Moderate" ? 55 : 35)) > safeNumber(best.riskScore || (best.riskLevel === "High" ? 80 : best.riskLevel === "Moderate" ? 55 : 35)) ? current : best), enrichedProperties[0]) : { propertyName: "Insufficient Data", value: 0 },
    mostStableAsset: enrichedProperties.length ? enrichedProperties.reduce((best, current) => (safeNumber(current.riskScore || (current.riskLevel === "High" ? 80 : current.riskLevel === "Moderate" ? 55 : 35)) < safeNumber(best.riskScore || (best.riskLevel === "High" ? 80 : best.riskLevel === "Moderate" ? 55 : 35)) ? current : best), enrichedProperties[0]) : { propertyName: "Insufficient Data", value: 0 },
  };

  const zipConcentration = Object.entries(enrichedProperties.reduce((acc, property) => {
    const key = property.zipCode || "Unknown";
    acc[key] = (acc[key] || 0) + safeNumber(property.currentValue);
    return acc;
  }, {})).sort((a, b) => b[1] - a[1])[0] || [];
  const zipExposure = safeNumber(zipConcentration[1] || 0);
  const portfolioAlerts = [
    ...(zipExposure > 0 && zipExposure / Math.max(totalCurrentValue, 1) > 0.35 ? [{ type: "overexposure-zip", severity: "HIGH", message: "ZIP concentration is above 35% of portfolio value." }] : []),
    ...(totalRehabBudget > 0 && totalRehabBudget / Math.max(totalCurrentValue, 1) > 0.2 ? [{ type: "rehab-budget-risk", severity: "MEDIUM", message: "Rehab budget exceeds 20% of portfolio market value." }] : []),
    ...(reserveShortfallValue > 0 ? [{ type: "liquidity-warning", severity: "HIGH", message: "Reserve coverage is below target and liquidity should be preserved." }] : []),
  ];

  const portfolioForecasts = buildPortfolioForecasts({
    totalCurrentValue,
    totalEquity: totalEquityValue,
    totalMonthlyCashFlow,
    totalMonthlyRent,
    totalSupportedArv: supportedArvValue,
    averageRoi: portfolioMetrics.averageRoi,
    healthScore: health.score,
    availableLiquidity: 250000,
  }, enrichedProperties);
  const portfolioForecastScenarios = buildPortfolioForecastScenarios(portfolioForecasts);
  const portfolioForecastSummary = buildPortfolioForecastSummary(portfolioForecasts, portfolioForecastScenarios);

  const summary = {
    totalProperties,
    activeDeals: Math.max(0, normalizedDeals.length),
    activeRehabs: rehabStats.activeRehabCount,
    rentalProperties: enrichedProperties.filter((property) => safeNumber(property.monthlyRent) > 0).length,
    propertiesListedForSale: enrichedProperties.filter((property) => property.status === "Listed" || property.status === "For Sale").length,
    propertiesUnderContract: enrichedProperties.filter((property) => property.status === "Under Contract" || property.status === "Under Contract" || property.status === "Contracted").length,
    propertiesHeldForRefinance: enrichedProperties.filter((property) => property.refinanceCandidate).length,
    totalAcquisitionCost: totalCurrentValue,
    totalRehabBudget: totalRehabBudget,
    totalActualRehabCost: totalActualRehabCost,
    totalCapitalInvested: totalCurrentValue + totalRehabBudget,
    totalCurrentValue,
    totalSupportedArv: supportedArvValue,
    totalAppraisedValue: enrichedProperties.reduce((sum, property) => sum + safeNumber(property.appraisedValue), 0),
    totalOutstandingDebt,
    totalEquity: totalEquityValue,
    portfolioLtv: portfolioLtvValue > 0 ? formatPercent(portfolioLtvValue) : "Insufficient Data",
    portfolioLtvValue,
    portfolioLtarv: portfolioLtarvValue > 0 ? formatPercent(portfolioLtarvValue) : "Insufficient Data",
    portfolioLTARVValue: portfolioLtarvValue,
    totalMonthlyRent,
    totalMonthlyOperatingExpenses,
    totalMonthlyDebtService,
    totalMonthlyCashFlow,
    totalAnnualCashFlow,
    portfolioNoi: portfolioNoiValue > 0 || portfolioNoiValue === 0 ? formatCurrency(portfolioNoiValue) : "Insufficient Data",
    portfolioNoiValue,
    portfolioCapRate: totalCurrentValue > 0 ? formatPercent((portfolioNoiValue / totalCurrentValue) * 100) : "Insufficient Data",
    portfolioCapRateValue: totalCurrentValue > 0 ? (portfolioNoiValue / totalCurrentValue) * 100 : 0,
    portfolioDscr: portfolioDscrValue > 0 ? `${portfolioDscrValue.toFixed(2)}x` : "Insufficient Data",
    portfolioDscrValue,
    totalProjectedFlipProfit: enrichedProperties.reduce((sum, property) => sum + safeNumber(property.projectedProfit), 0),
    totalRealizedProfit: enrichedProperties.reduce((sum, property) => sum + safeNumber(property.actualProfit), 0),
    totalUnrealizedProfit: enrichedProperties.reduce((sum, property) => sum + safeNumber(property.projectedProfit), 0) - enrichedProperties.reduce((sum, property) => sum + safeNumber(property.actualProfit), 0),
    cashRequiredForActiveProjects: enrichedProperties.reduce((sum, property) => sum + safeNumber(property.rehabNeed), 0),
    availableLiquidity: 250000,
    recommendedReserve: recommendedReserveValue,
    reserveShortfallValue,
    reserveSurplusOrShortfall: reserveShortfallValue > 0 ? `Shortfall ${formatCurrency(reserveShortfallValue)}` : `Surplus ${formatCurrency(Math.max(0, recommendedReserveValue - 250000))}`,
    upcomingMaturities: enrichedProperties.filter((property) => property.loanMaturityRisk !== "Insufficient Data" && property.loanMaturityRisk !== "Low").length,
    healthScore: health.score,
    healthGrade: health.grade,
    healthStatus: health.status,
    healthExplanation: health.explanation,
    criticalAlertCount,
    totalPropertiesWithNegativeCashFlow: enrichedProperties.filter((property) => property.cashFlowRisk === "Negative").length,
    propertiesWithNegativeCashFlow: enrichedProperties.filter((property) => property.cashFlowRisk === "Negative").length,
    totalPropertiesWithNegativeEquity: enrichedProperties.filter((property) => property.negativeEquity).length,
    propertiesWithNegativeEquity: enrichedProperties.filter((property) => property.negativeEquity).length,
    totalPropertiesWithRefinanceCandidate: enrichedProperties.filter((property) => property.refinanceCandidate).length,
    propertiesWithRefinanceCandidate: enrichedProperties.filter((property) => property.refinanceCandidate).length,
    totalPropertiesWithSellCandidate: enrichedProperties.filter((property) => property.sellCandidate).length,
    propertiesWithSellCandidate: enrichedProperties.filter((property) => property.sellCandidate).length,
    totalPropertiesWithActiveRehab: rehabStats.activeRehabCount,
    totalPropertiesWithDocumentationRisk: enrichedProperties.filter((property) => !property.supportedArv).length,
    ...portfolioMetrics,
  };

  const enterpriseUpgrade2 = buildPortfolioEnterpriseUpgradeEngine({
    summary,
    properties: enrichedProperties,
    contractors: normalizedContractors,
    rehabProjects: normalizedRehabProjects,
    assumptions: {
      appreciationRate: null,
      rentGrowthRate: null,
      expenseGrowthRate: null,
    },
    providerStatus: {},
    marketSnapshot: {},
    auditUpdates: [],
  });

  return {
    summary,
    health,
    alerts,
    portfolioAlerts,
    priorities,
    topOpportunity,
    portfolioHighlights,
    portfolioForecasts,
    portfolioForecastScenarios,
    portfolioForecastSummary,
    integrityAudit: buildIntegrityAudit(summary, portfolioForecasts, portfolioForecastScenarios),
    capitalPosition,
    businessStatus: health.status,
    portfolioHealth: health.status,
    capitalStatus: capitalPosition.status,
    properties: enrichedProperties,
    rankings: enrichedProperties
      .map((property) => ({
        property: property.propertyName,
        address: property.propertyAddress,
        strategy: property.strategy,
        status: property.status,
        currentValue: formatCurrency(property.currentValue),
        debt: formatCurrency(property.debt),
        equity: formatCurrency(property.equity),
        ltv: formatPercent(property.currentValue > 0 ? (property.debt / property.currentValue) * 100 : 0),
        monthlyCashFlow: formatCurrency(property.monthlyCashFlow),
        dscr: property.monthlyDebtService > 0 ? `${((property.monthlyRent * 12 - property.monthlyOperatingExpenses * 12 - property.monthlyDebtService * 12) / (property.monthlyDebtService * 12)).toFixed(2)}x` : "Insufficient Data",
        projectedProfit: formatCurrency(property.rehabNeed),
        roi: formatPercent(property.currentValue > 0 ? ((property.currentValue - safeNumber(property.purchasePrice)) / safeNumber(property.purchasePrice)) * 100 : 0),
        risk: property.riskLevel,
        recommendation: property.recommendation,
        requiredAction: property.refinanceCandidate ? "Review refinance" : property.sellCandidate ? "Review sale" : "Monitor",
        openProperty: property.propertyName,
        openDealIntelligence: property.propertyName,
      }))
      .sort((a, b) => (safeNumber(b.currentValue) > safeNumber(a.currentValue) ? 1 : -1)),
    capitalAllocation: buildCapitalAllocation(enrichedProperties, summary),
    refinanceOpportunities: buildRefinanceOpportunities(enrichedProperties),
    sellVsHold: buildSellVsHold(enrichedProperties),
    brrrrRecycling: buildBrrrrRecycling(enrichedProperties),
    debtMaturitySchedule: buildDebtMaturitySchedule(enrichedProperties),
    rehabCapacity: buildRehabCapacity(enrichedProperties),
    concentrationRisk,
    portfolioBalancingEngine,
    enterpriseUpgrade2,
    stressTests: buildStressTests(enrichedProperties, summary),
    known: [
      `Portfolio contains ${summary.totalProperties} properties`,
      `Current total value is ${formatCurrency(summary.totalCurrentValue)}`,
      `Outstanding debt is ${formatCurrency(summary.totalOutstandingDebt)}`,
      `Portfolio health score is ${summary.healthScore}`,
    ],
    uncertain: [
      "Some rents and operating assumptions are unverified",
      "Some loan balances and maturity dates remain incomplete",
      "Some property-level underwriting may require refresh",
    ],
    neededToImproveDecision: [
      "Updated valuations",
      "Updated loan balances",
      "Verified rents",
      "Current contractor budgets",
      "Appraisals",
      "Loan maturity dates",
    ],
    notes: normalizedNotes,
  };
}

export function safeNumber(value) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
}

export function safeDisplay(value, fallback = "Insufficient Data") {
  if (value === null || value === undefined || value === "" || Number.isNaN(value)) return fallback;
  if (typeof value === "number" && !Number.isFinite(value)) return fallback;
  if (typeof value === "object") return fallback;
  return value;
}

function normalizeDeal(deal) {
  return deal && typeof deal === "object" && !Array.isArray(deal) ? deal : {};
}

function normalizeAnalysis(analysis) {
  return analysis && typeof analysis === "object" && !Array.isArray(analysis) ? analysis : {};
}

function normalizeScenarioData(scenarioData) {
  return scenarioData && typeof scenarioData === "object" && !Array.isArray(scenarioData) ? scenarioData : {};
}

function asArray(value) {
  return Array.isArray(value) ? value : [];
}

function hasMeaningfulData(deal, analysis, scenarioData) {
  const dealValues = [
    deal.purchasePrice,
    deal.askingPrice,
    deal.rehabBudget,
    deal.estimatedArv,
    deal.arv,
    deal.projectedARV,
    deal.currentValue,
    deal.estimatedRent,
    deal.marketRent,
    deal.projectedRent,
    deal.vacancyRate,
    deal.vacancy,
    deal.taxes,
    deal.insurance,
    deal.cashOnHand,
    deal.appraisedValue,
  ];
  const analysisValues = [
    analysis.dealScore,
    analysis.estimatedFlipProfit,
    analysis.roi,
    analysis.dscr,
    analysis.monthlyCashFlow,
    analysis.cashRequired,
    analysis.supportedBaseArv,
    analysis.marketScore,
    analysis.valuationScore,
  ];
  const scenarioValues = [
    scenarioData?.summary?.baseRecommendation,
    scenarioData?.summary?.scenarioSurvivalResult,
    scenarioData?.summary?.expectedProfit,
    scenarioData?.summary?.expectedRoi,
    scenarioData?.summary?.downsideMonthlyCashFlow,
  ];
  return [...dealValues, ...analysisValues, ...scenarioValues].some((value) => value !== null && value !== undefined && value !== "" && value !== 0);
}

function getScenarioSummaryValue(scenarioData, key) {
  const scenarios = asArray(scenarioData?.scenarios || []);
  const entry = scenarios.find((candidate) => candidate?.scenarioName === "Moderate Downside") || scenarios[0] || {};
  return entry?.summary?.[key];
}

function getHighestRiskWarning(analysis) {
  const warnings = asArray(analysis?.warnings || []);
  return warnings[0] || "Insufficient Data";
}

function buildChallenge(title, baseAssumption, challengedAssumption, financialEffect, scoreEffect, riskEffect, recommendationEffect, supportingWarnings, requiredActions) {
  return {
    title,
    baseAssumption,
    challengedAssumption,
    financialEffect,
    scoreEffect,
    riskEffect,
    recommendationEffect,
    supportingWarnings: asArray(supportingWarnings),
    requiredActions: asArray(requiredActions),
  };
}

export function buildRedTeamReview(dealInput = {}, analysisInput = {}, scenarioInput = {}) {
  try {
    const deal = normalizeDeal(dealInput);
    const analysis = normalizeAnalysis(analysisInput);
    const scenarioData = normalizeScenarioData(scenarioInput);

    if (!hasMeaningfulData(deal, analysis, scenarioData)) {
      return {
        strongestArgumentAgainstDeal: "Insufficient Data",
        mostFragileAssumption: "Insufficient Data",
        mostImportantMissingInformation: "Insufficient Data",
        largestFinancialRisk: "Insufficient Data",
        largestExecutionRisk: "Insufficient Data",
        largestMarketRisk: "Insufficient Data",
        largestFinancingRisk: "Insufficient Data",
        largestExitRisk: "Insufficient Data",
        downsideRecommendation: "Insufficient Data",
        recommendationSurvivalResult: "Insufficient Data",
        recommendationConfidence: "Insufficient Data",
        confidenceReasons: ["Red-Team Review unavailable for this deal."],
        decisionBreakingAssumption: "Insufficient Data",
        requiredCorrectiveActions: [],
        challenges: [],
        summary: {
          survivalResult: "Insufficient Data",
          recommendationConfidence: "Insufficient Data",
          fragileAssumption: "Insufficient Data",
          decisionBreakingThreshold: "Insufficient Data",
          downsideRecommendation: "Insufficient Data",
          criticalRiskCount: 0,
          decisionBlockingActionCount: 0,
        },
        metadata: {},
      };
    }

    const purchasePrice = safeNumber(deal.purchasePrice ?? deal.askingPrice);
    const rehabBudget = safeNumber(deal.rehabBudget);
    const arv = safeNumber(deal.estimatedArv ?? deal.arv ?? deal.projectedARV ?? deal.currentValue);
    const supportedArv = safeNumber(analysis.supportedBaseArv ?? deal.supportedBaseArv ?? 0);
    const appraisedValue = safeNumber(deal.appraisedValue ?? 0);
    const estimatedRent = safeNumber(deal.estimatedRent ?? deal.marketRent ?? deal.projectedRent);
    const vacancyRate = safeNumber(deal.vacancyRate ?? deal.vacancy ?? 0);
    const financingCosts = safeNumber(deal.financingCosts);
    const closingCosts = safeNumber(deal.closingCosts);
    const taxes = safeNumber(deal.taxes);
    const insurance = safeNumber(deal.insurance);
    const cashOnHand = safeNumber(deal.cashOnHand);
    const monthlyCashFlow = safeNumber(analysis.monthlyCashFlow ?? 0);
    const dscr = safeNumber(analysis.dscr ?? 0);
    const cashRequired = safeNumber(analysis.cashRequired ?? 0);
    const dealScore = safeNumber(analysis.dealScore ?? 0);
    const overallRisk = safeNumber(analysis.overallRisk ?? 0);
    const warnings = asArray(analysis.warnings || []);
    const financingWarnings = asArray(analysis.financingWarnings || []);
    const compCount = safeNumber(analysis.compCount ?? 0);
    const buyBoxResult = safeDisplay(analysis.buyBoxResult || deal.buyBoxResult, "Insufficient Data");
    const arvConfidence = safeDisplay(analysis.arvConfidence || deal.arvConfidence, "Insufficient Data");
    const marketScore = safeNumber(analysis.marketScore ?? 0);
    const valuationScore = safeNumber(analysis.valuationScore ?? 0);
    const recommendedExit = safeDisplay(analysis.recommendedExit || deal.recommendedExit, "Insufficient Data");
    const scenarioSummary = normalizeScenarioData(scenarioData?.summary || {});
    const scenarioSummaryProfit = safeNumber(getScenarioSummaryValue(scenarioData, "profit") ?? scenarioSummary.expectedProfit ?? 0);
    const scenarioSummaryRoi = safeNumber(getScenarioSummaryValue(scenarioData, "roi") ?? scenarioSummary.expectedRoi ?? 0);
    const scenarioSummaryMonthlyCashFlow = safeNumber(getScenarioSummaryValue(scenarioData, "monthlyCashFlow") ?? scenarioSummary.downsideMonthlyCashFlow ?? 0);
    const scenarioSummaryDscr = safeNumber(getScenarioSummaryValue(scenarioData, "dscr") ?? 0);
    const scenarioSurvivalResult = safeDisplay(scenarioData?.summary?.scenarioSurvivalResult || analysis.scenarioSurvivalResult, "Insufficient Data");

    const requiredCorrectiveActions = [];
    if (supportedArv <= 0 || compCount < 3) requiredCorrectiveActions.push("Order appraisal");
    if (rehabBudget > 0 && rehabBudget > 50000) requiredCorrectiveActions.push("Increase rehab contingency");
    if (cashRequired > cashOnHand) requiredCorrectiveActions.push("Increase available liquidity");
    if (estimatedRent <= 0) requiredCorrectiveActions.push("Verify achievable rent");
    if (financingWarnings.length) requiredCorrectiveActions.push("Request revised lender terms");
    if (buyBoxResult !== "PASS") requiredCorrectiveActions.push("Re-underwrite against the target buy box");
    if (!warnings.length) requiredCorrectiveActions.push("Confirm supporting comps");
    if (recommendedExit === "Hold" || recommendedExit === "Insufficient Data") requiredCorrectiveActions.push("Add a secondary exit strategy");

    const strongestArgumentAgainstDeal = (() => {
      if (recommendedExit === "Hold" || recommendedExit === "Insufficient Data") return "The deal relies on too many assumptions to support a confident recommendation.";
      if (supportedArv <= 0 || compCount < 3) return "The deal lacks sufficient comp and valuation support to justify the current ARV assumption.";
      if (monthlyCashFlow < 0 || dscr < 1) return "The deal produces weak or negative operating economics under current assumptions.";
      if (cashRequired > cashOnHand) return "The required cash contribution exceeds available liquidity and could break the deal.";
      if (warnings.length || financingWarnings.length) return "The current recommendation is vulnerable to unresolved underwriting and lender concerns.";
      return "The recommendation depends on one or more optimistic assumptions that are not yet fully supported.";
    })();

    const mostFragileAssumption = (() => {
      if (supportedArv <= 0 || compCount < 3) return "Supported ARV is not yet established.";
      if (rehabBudget > 0 && rehabBudget > 50000) return "Rehab budget may be understated relative to scope.";
      if (estimatedRent <= 0) return "Rental income assumption is not supported by market data.";
      if (cashRequired > cashOnHand) return "Required cash contribution may exceed available liquidity.";
      if (dscr < 1.2) return "DSCR is too weak to support the recommendation.";
      if (warnings.some((warning) => warning.toLowerCase().includes("buy box"))) return "The property may fall outside the buy box.";
      return "The recommendation depends on a single optimistic assumption.";
    })();

    const mostImportantMissingInformation = (() => {
      if (supportedArv <= 0 || compCount < 3) return "Independent ARV support from comps or appraisal";
      if (rehabBudget <= 0) return "Rehab scope and contingency detail";
      if (cashRequired > cashOnHand) return "Liquidity confirmation and cash-to-close detail";
      if (estimatedRent <= 0) return "Verified rent and operating assumptions";
      return "Lender terms and exit strategy support";
    })();

    const largestFinancialRisk = (() => {
      if (scenarioSummaryProfit < 0 || monthlyCashFlow < 0) return "Negative projected profit";
      if (scenarioSummaryMonthlyCashFlow < 0 || monthlyCashFlow < 0) return "Negative monthly cash flow";
      if (cashRequired > cashOnHand) return "Cash-to-close exceeds available liquidity";
      return "Weak downside margin";
    })();

    const largestExecutionRisk = (() => {
      if (rehabBudget > 50000) return "Rehab scope and contingency may be understated";
      if (warnings.some((warning) => warning.toLowerCase().includes("rehab"))) return "Rehab timing and contractor execution may deteriorate";
      return "Project execution may be slower and more costly than planned";
    })();

    const largestMarketRisk = (() => {
      if (marketScore < 60) return "Market support is weak";
      if (vacancyRate > 0.05) return "Vacancy assumptions may be understated";
      if (warnings.some((warning) => warning.toLowerCase().includes("buy box"))) return "The property may sit outside the target market";
      return "Market liquidity may be weaker than planned";
    })();

    const largestFinancingRisk = (() => {
      if (financingWarnings.length) return financingWarnings[0];
      if (cashRequired > cashOnHand) return "Liquidity requirement may exceed available cash";
      if (dscr < 1.2) return "DSCR is too weak for current lender terms";
      return "Financing terms may tighten under downside conditions";
    })();

    const largestExitRisk = (() => {
      if (recommendedExit === "Flip") return "Flip exit may be constrained by slow market liquidity";
      if (recommendedExit === "BRRRR") return "Refinance proceeds may not support the exit";
      return "Secondary exit support is weak or unavailable";
    })();

    const downsideRecommendation = (() => {
      if (scenarioSurvivalResult === "Fails" || scenarioSummaryProfit < 0 || monthlyCashFlow < 0 || dscr < 1) return "Reject";
      if (scenarioSurvivalResult === "Marginal" || scenarioSummaryRoi < 0.05 || scenarioSummaryMonthlyCashFlow < 0) return "Hold";
      if (scenarioSurvivalResult === "Survives with Conditions") return "Conditional Buy";
      return "Conditional Buy";
    })();

    let recommendationSurvivalResult = "Insufficient Data";
    if (scenarioSurvivalResult === "Fails") recommendationSurvivalResult = "Fails";
    else if (scenarioSurvivalResult === "Marginal") recommendationSurvivalResult = "Marginal";
    else if (scenarioSurvivalResult === "Survives with Conditions") recommendationSurvivalResult = "Survives with Conditions";
    else if (scenarioSurvivalResult === "Survives") recommendationSurvivalResult = "Survives";

    let recommendationConfidence = "Insufficient Data";
    let confidenceReasons = [];
    if (scenarioSurvivalResult === "Fails" || scenarioSummaryProfit < 0 || monthlyCashFlow < 0 || dscr < 1 || cashRequired > cashOnHand) {
      recommendationConfidence = "Very Low";
    } else if (scenarioSurvivalResult === "Marginal" || supportedArv <= 0 || compCount < 3 || buyBoxResult !== "PASS" || marketScore < 60 || financingWarnings.length > 0 || warnings.length > 0) {
      recommendationConfidence = "Low";
    } else if (scenarioSurvivalResult === "Survives with Conditions") {
      recommendationConfidence = "Moderate";
    } else if (scenarioSurvivalResult === "Survives") {
      recommendationConfidence = "High";
    }

    confidenceReasons = [
      `ARV confidence: ${safeDisplay(arvConfidence, "Insufficient Data")}`,
      `Comp quality: ${compCount >= 3 ? "Three or more valid comps" : "Insufficient comp support"}`,
      `Market support: ${marketScore >= 70 ? "Strong" : marketScore >= 50 ? "Moderate" : "Weak"}`,
      `Scenario survival: ${safeDisplay(scenarioSurvivalResult, "Insufficient Data")}`,
      `Documentation and lender support: ${financingWarnings.length === 0 ? "Reasonable" : "Needs attention"}`,
    ];

    const decisionBreakingAssumption = (() => {
      if (supportedArv <= 0 || compCount < 3) {
        const minimumProfitBuffer = Math.max(5000, Math.round((purchasePrice + rehabBudget) * 0.08));
        const decisionBreakingArv = purchasePrice + rehabBudget + financingCosts + closingCosts + taxes + insurance + minimumProfitBuffer;
        return `Supported ARV must remain above $${Math.round(decisionBreakingArv).toLocaleString()} to preserve a minimum profit buffer of $${minimumProfitBuffer.toLocaleString()}.`;
      }
      if (rehabBudget > 0 && rehabBudget > 50000) return `Rehab must remain below $${Math.max(0, rehabBudget).toLocaleString()} to preserve the recommendation.`;
      if (estimatedRent > 0) return `Monthly rent must remain above $${Math.round(estimatedRent).toLocaleString()} to preserve the recommendation.`;
      if (cashRequired > 0) return `Purchase price must remain below $${Math.round(purchasePrice).toLocaleString()} to preserve the recommendation.`;
      if (dscr > 0) return `DSCR must remain above ${dscr.toFixed(2)} to preserve the recommendation.`;
      return "Insufficient Data";
    })();

    const challenges = [
      buildChallenge(
        "Valuation Challenge",
        `Projected ARV ${formatCurrency(arv)}; Supported ARV ${formatCurrency(supportedArv)}`,
        `Projected ARV exceeds supported ARV or lacks support from comps/appraisal`,
        `Projected downside ARV impact: ${formatCurrency(Math.max(0, arv - supportedArv))}`,
        `Score effect: ${supportedArv <= 0 || compCount < 3 ? "Materially reduced" : "Moderate"}`,
        `Risk effect: ${supportedArv <= 0 || compCount < 3 ? "High" : "Moderate"}`,
        `Recommendation effect: ${supportedArv <= 0 || compCount < 3 ? "Weakens materially" : "Re-underwrite may be needed"}`,
        [supportedArv <= 0 || compCount < 3 ? "Insufficient comp support" : "ARV support is thin"],
        requiredCorrectiveActions.filter((action) => action.includes("appraisal") || action.includes("comps")),
      ),
      buildChallenge(
        "Rehab Challenge",
        `Rehab budget ${formatCurrency(rehabBudget)}`,
        `Rehab +10% / +20% / +30% and contingency exhaustion materially increase cost`,
        `Budget overrun impact: ${formatCurrency(rehabBudget * 0.3)}`,
        `Score effect: ${rehabBudget > 50000 ? "Materially reduced" : "Moderate"}`,
        `Risk effect: ${rehabBudget > 50000 ? "High" : "Moderate"}`,
        `Recommendation effect: ${rehabBudget > 50000 ? "Weakens materially" : "Needs review"}`,
        [rehabBudget > 50000 ? "Rehab budget may be understated" : "Rehab contingency not yet confirmed"],
        [rehabBudget > 50000 ? "Increase rehab contingency" : "Confirm rehab scope"],
      ),
      buildChallenge(
        "Financing Challenge",
        `Current financing requires ${formatCurrency(cashRequired)} cash and DSCR ${dscr.toFixed(2)}`,
        `Higher rate, fees, tighter LTC/LTARV, or lower DSCR pressure the deal`,
        `Monthly payment impact: ${formatCurrency(Math.max(0, cashRequired * 0.01))}`,
        `Score effect: ${financingWarnings.length ? "Materially reduced" : "Moderate"}`,
        `Risk effect: ${financingWarnings.length ? "High" : "Moderate"}`,
        `Recommendation effect: ${financingWarnings.length ? "Weakens materially" : "Needs lender review"}`,
        financingWarnings,
        requiredCorrectiveActions.filter((action) => action.includes("lender") || action.includes("liquidity")),
      ),
      buildChallenge(
        "Rental Challenge",
        `Current rent ${formatCurrency(estimatedRent)} and vacancy ${formatPercent(vacancyRate)}`,
        `Lower rent, higher vacancy, and higher operating expenses compress cash flow`,
        `Monthly cash flow impact: ${formatCurrency(Math.max(0, monthlyCashFlow * -1))}`,
        `Score effect: ${estimatedRent > 0 ? "Moderate" : "Materially reduced"}`,
        `Risk effect: ${estimatedRent > 0 ? "Moderate" : "High"}`,
        `Recommendation effect: ${estimatedRent > 0 ? "Weakens" : "Fails"}`,
        [estimatedRent <= 0 ? "Rent is unsupported" : "Rent sensitivity remains"],
        [estimatedRent <= 0 ? "Verify achievable rent" : "Re-check operating assumptions"],
      ),
      buildChallenge(
        "Market Challenge",
        `Buy box result ${buyBoxResult}; market score ${marketScore}`,
        `Outside buy box, weak rental demand, slow market, or weak liquidity pressure the value`,
        `Market support impact: ${marketScore < 60 ? "Material" : "Moderate"}`,
        `Score effect: ${marketScore < 60 ? "Materially reduced" : "Moderate"}`,
        `Risk effect: ${marketScore < 60 ? "High" : "Moderate"}`,
        `Recommendation effect: ${marketScore < 60 ? "Weakens materially" : "Needs market review"}`,
        warnings,
        requiredCorrectiveActions.filter((action) => action.includes("buy box") || action.includes("exit") || action.includes("strategy")),
      ),
      buildChallenge(
        "Exit Challenge",
        `Primary exit ${recommendedExit}`,
        `If the primary exit stalls, backup exit viability becomes the key concern`,
        `Exit viability impact: ${recommendedExit === "Insufficient Data" ? "High" : "Moderate"}`,
        `Score effect: ${recommendedExit === "Insufficient Data" ? "Materially reduced" : "Moderate"}`,
        `Risk effect: ${recommendedExit === "Insufficient Data" ? "High" : "Moderate"}`,
        `Recommendation effect: ${recommendedExit === "Insufficient Data" ? "Weakens materially" : "Needs backup plan"}`,
        [recommendedExit === "Hold" ? "No clear secondary exit" : "Exit still depends on market conditions"],
        [recommendedExit === "Hold" ? "Add a secondary exit strategy" : "Confirm backup exit"],
      ),
      buildChallenge(
        "Documentation Challenge",
        `Current warnings: ${warnings.length || 0}`,
        `Missing inspection, appraisal, title, insurance, lender, or scope documents can block the deal`,
        `Documentation impact: ${warnings.length ? "Material" : "Moderate"}`,
        `Score effect: ${warnings.length ? "Materially reduced" : "Moderate"}`,
        `Risk effect: ${warnings.length ? "High" : "Moderate"}`,
        `Recommendation effect: ${warnings.length ? "Weakens materially" : "Needs review"}`,
        warnings,
        requiredCorrectiveActions.filter((action) => action.includes("appraisal") || action.includes("review") || action.includes("scope")),
      ),
    ];

    return {
      strongestArgumentAgainstDeal,
      mostFragileAssumption,
      mostImportantMissingInformation,
      largestFinancialRisk,
      largestExecutionRisk,
      largestMarketRisk,
      largestFinancingRisk,
      largestExitRisk,
      downsideRecommendation,
      recommendationSurvivalResult,
      recommendationConfidence,
      confidenceReasons,
      decisionBreakingAssumption,
      requiredCorrectiveActions,
      challenges,
      summary: {
        survivalResult: recommendationSurvivalResult,
        recommendationConfidence,
        fragileAssumption: mostFragileAssumption,
        decisionBreakingThreshold: decisionBreakingAssumption,
        downsideRecommendation,
        criticalRiskCount: [largestFinancialRisk, largestExecutionRisk, largestMarketRisk, largestFinancingRisk, largestExitRisk].filter((entry) => entry && entry !== "Insufficient Data").length,
        decisionBlockingActionCount: requiredCorrectiveActions.filter((action) => action.includes("appraisal") || action.includes("lender") || action.includes("buy box") || action.includes("liquidity")).length,
      },
      metadata: {
        dealScore,
        overallRisk,
        buyBoxResult,
        arvConfidence,
        scenarioSurvivalResult,
      },
    };
  } catch (error) {
    return {
      strongestArgumentAgainstDeal: "Insufficient Data",
      mostFragileAssumption: "Insufficient Data",
      mostImportantMissingInformation: "Insufficient Data",
      largestFinancialRisk: "Insufficient Data",
      largestExecutionRisk: "Insufficient Data",
      largestMarketRisk: "Insufficient Data",
      largestFinancingRisk: "Insufficient Data",
      largestExitRisk: "Insufficient Data",
      downsideRecommendation: "Insufficient Data",
      recommendationSurvivalResult: "Insufficient Data",
      recommendationConfidence: "Insufficient Data",
      confidenceReasons: ["Red-Team Review unavailable for this deal."],
      decisionBreakingAssumption: "Insufficient Data",
      requiredCorrectiveActions: [],
      challenges: [],
      summary: {
        survivalResult: "Insufficient Data",
        recommendationConfidence: "Insufficient Data",
        fragileAssumption: "Insufficient Data",
        decisionBreakingThreshold: "Insufficient Data",
        downsideRecommendation: "Insufficient Data",
        criticalRiskCount: 0,
        decisionBlockingActionCount: 0,
      },
      metadata: {},
    };
  }
}

function formatCurrency(value) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) return "Insufficient Data";
  return `$${parsed.toLocaleString("en-US", { maximumFractionDigits: 0 })}`;
}

function formatPercent(value) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) return "Insufficient Data";
  return `${(parsed * 100).toFixed(1)}%`;
}

function safeNumber(value) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
}

function safeDisplay(value, fallback = 'Insufficient Data') {
  if (value === null || value === undefined || value === '' || Number.isNaN(value)) return fallback;
  if (typeof value === 'number' && !Number.isFinite(value)) return fallback;
  if (typeof value === 'object') return fallback;
  return value;
}

function formatCurrency(value) {
  const parsed = safeNumber(value);
  if (!Number.isFinite(parsed)) return 'Insufficient Data';
  return `$${parsed.toLocaleString('en-US', { maximumFractionDigits: 0 })}`;
}

function formatPercent(value) {
  const parsed = safeNumber(value);
  if (!Number.isFinite(parsed)) return 'Insufficient Data';
  return `${parsed.toFixed(1)}%`;
}

function safeArray(value) {
  return Array.isArray(value) ? value : [];
}

function safeObject(value) {
  return value && typeof value === 'object' ? value : {};
}

function buildSafeOptimizerResult(overrides = {}) {
  const summary = overrides.summary && typeof overrides.summary === 'object' ? overrides.summary : {};
  const refinanceAnalysis = overrides.refinanceAnalysis && typeof overrides.refinanceAnalysis === 'object' ? overrides.refinanceAnalysis : {};

  return {
    status: overrides.status || 'Unavailable',
    primaryExit: overrides.primaryExit ?? 'Insufficient Data',
    secondaryExit: overrides.secondaryExit ?? 'Insufficient Data',
    exitToAvoid: overrides.exitToAvoid ?? 'Insufficient Data',
    recommendedTiming: overrides.recommendedTiming ?? 'Insufficient Data',
    decisionStatus: overrides.decisionStatus ?? 'Insufficient Data',
    reason: overrides.reason ?? 'Refinance & Exit analysis unavailable for this deal.',
    refinanceReadiness: overrides.refinanceReadiness ?? 'Insufficient Data',
    exitScore: overrides.exitScore ?? 0,
    viability: overrides.viability ?? 'Insufficient Data',
    strategies: Array.isArray(overrides.strategies) ? overrides.strategies : [],
    comparison: Array.isArray(overrides.comparison) ? overrides.comparison : [],
    stressTests: Array.isArray(overrides.stressTests) ? overrides.stressTests : [],
    breakEvenThresholds: Array.isArray(overrides.breakEvenThresholds) ? overrides.breakEvenThresholds : [],
    warnings: Array.isArray(overrides.warnings) ? overrides.warnings : [],
    requiredActions: Array.isArray(overrides.requiredActions) ? overrides.requiredActions : [],
    summary: {
      message: summary.message || 'Refinance & Exit analysis unavailable for this deal.',
      ...summary,
    },
    refinanceAnalysis,
    timeline: Array.isArray(overrides.timeline) ? overrides.timeline : [],
    known: Array.isArray(overrides.known) ? overrides.known : [],
    uncertain: Array.isArray(overrides.uncertain) ? overrides.uncertain : [],
    needed: Array.isArray(overrides.needed) ? overrides.needed : [],
    capitalIntegration: overrides.capitalIntegration && typeof overrides.capitalIntegration === 'object' ? overrides.capitalIntegration : {},
    portfolioSummary: overrides.portfolioSummary && typeof overrides.portfolioSummary === 'object' ? overrides.portfolioSummary : {},
  };
}

function getSupportedValue(property) {
  const appraisedValue = safeNumber(property.appraisedValue ?? property.appraisalValue);
  const supportedArv = safeNumber(property.supportedARV ?? property.projectedARV ?? property.estimatedArv);
  const currentValue = safeNumber(property.currentValue ?? property.currentEstimatedValue ?? property.value);
  if (appraisedValue > 0) return appraisedValue;
  if (supportedArv > 0) return supportedArv;
  if (currentValue > 0) return currentValue;
  return 0;
}

function getAnnualNoi(property) {
  const monthlyRent = safeNumber(property.monthlyRent ?? property.effectiveRent);
  const monthlyOperatingExpenses = safeNumber(property.monthlyOperatingExpenses ?? property.operatingExpenses);
  const monthlyDebtService = safeNumber(property.monthlyDebtService ?? property.debtService ?? property.payment);
  return (monthlyRent - monthlyOperatingExpenses - monthlyDebtService) * 12;
}

function getDscr(property) {
  const annualNoi = getAnnualNoi(property);
  const annualDebtService = safeNumber(property.monthlyDebtService ?? property.debtService ?? property.payment) * 12;
  if (annualDebtService <= 0) return 0;
  return annualNoi / annualDebtService;
}

function buildStrategy(option) {
  return {
    strategy: option.strategy,
    viability: option.viability,
    estimatedValue: option.estimatedValue,
    estimatedGrossProceeds: option.estimatedGrossProceeds,
    estimatedNetProceeds: option.estimatedNetProceeds,
    capitalRequired: option.capitalRequired,
    capitalReturned: option.capitalReturned,
    profit: option.profit,
    roi: option.roi,
    annualizedRoi: option.annualizedRoi,
    monthlyCashFlow: option.monthlyCashFlow,
    annualCashFlow: option.annualCashFlow,
    dscr: option.dscr,
    cashLeftInDeal: option.cashLeftInDeal,
    timeToExit: option.timeToExit,
    liquidityImpact: option.liquidityImpact,
    reserveImpact: option.reserveImpact,
    riskLevel: option.riskLevel,
    scenarioSurvival: option.scenarioSurvival,
    dataConfidence: option.dataConfidence,
    mainAdvantage: option.mainAdvantage,
    mainWeakness: option.mainWeakness,
    requiredConditions: option.requiredConditions,
    requiredNextAction: option.requiredNextAction,
    exitScore: option.exitScore,
    grade: option.grade,
    explanation: option.explanation,
  };
}

export function buildRefinanceExitOptimizer(payload = {}) {
  const properties = safeArray(payload.properties);
  const deals = safeArray(payload.deals);
  const portfolioIntelligence = safeObject(payload.portfolioIntelligence);
  const capitalAllocationEngine = safeObject(payload.capitalAllocationEngine);

  if (!properties.length) {
    return buildSafeOptimizerResult({
      status: 'Unavailable',
      primaryExit: 'Insufficient Data',
      secondaryExit: 'Insufficient Data',
      exitToAvoid: 'Insufficient Data',
      recommendedTiming: 'Insufficient Data',
      decisionStatus: 'Insufficient Data',
      reason: 'No supported properties were available for exit analysis.',
      refinanceReadiness: 'Insufficient Data',
      refinanceAnalysis: {
        readyToRefinance: false,
        refinanceValue: 0,
        refinanceLoanAmount: 0,
        grossRefinanceProceeds: 0,
        netRefinanceProceeds: 0,
        cashReturned: 0,
        cashLeftInDeal: 0,
        capitalRecoveryPercentage: 0,
        newMonthlyPayment: 0,
        postRefinanceMonthlyCashFlow: 0,
        postRefinanceDscr: 0,
      },
      comparison: [],
      breakEvenThresholds: [],
      stressTests: [],
      timeline: [],
      known: ['No property data was available for exit analysis.'],
      uncertain: ['The optimizer requires supported property and lender details to produce reliable exit guidance.'],
      needed: ['Property values', 'Loan payoff', 'Appraisal or ARV support', 'Rent and expenses'],
      capitalIntegration: {
        capitalRequired: 0,
        capitalReturned: 0,
        liquidityImpact: 'Insufficient Data',
      },
      summary: {
        message: 'Refinance & Exit analysis unavailable for this deal.',
        estimatedCapitalReleased: 'Insufficient Data',
        estimatedCapitalRequired: 'Insufficient Data',
        exitScore: 'Insufficient Data',
      },
    });
  }

  const supportedProperty = properties.find((property) => safeNumber(property.currentValue ?? property.currentEstimatedValue ?? property.value) > 0) || properties[0];
  const value = getSupportedValue(supportedProperty);
  const currentLoanBalance = safeNumber(supportedProperty.currentLoanBalance ?? supportedProperty.loanBalance ?? supportedProperty.currentDebt ?? supportedProperty.debt);
  const monthlyRent = safeNumber(supportedProperty.monthlyRent ?? supportedProperty.effectiveRent);
  const monthlyOperatingExpenses = safeNumber(supportedProperty.monthlyOperatingExpenses ?? supportedProperty.operatingExpenses);
  const monthlyDebtService = safeNumber(supportedProperty.monthlyDebtService ?? supportedProperty.debtService ?? supportedProperty.payment);
  const rehabRemainingBudget = safeNumber(supportedProperty.rehabRemainingBudget ?? supportedProperty.remainingRehabBudget ?? supportedProperty.rehabBudgetRemaining ?? supportedProperty.rehabNeed);
  const rehabPercentComplete = safeNumber(supportedProperty.rehabPercentComplete ?? supportedProperty.percentComplete ?? supportedProperty.rehabCompletionPercentage);
  const hasMeaningfulInput = value > 0 || currentLoanBalance > 0 || monthlyRent > 0 || monthlyDebtService > 0 || rehabRemainingBudget > 0 || rehabPercentComplete > 0;

  if (!hasMeaningfulInput) {
    return buildSafeOptimizerResult({
      status: 'Unavailable',
      primaryExit: 'Insufficient Data',
      secondaryExit: 'Insufficient Data',
      exitToAvoid: 'Insufficient Data',
      recommendedTiming: 'Insufficient Data',
      decisionStatus: 'Insufficient Data',
      reason: 'Refinance & Exit analysis unavailable for this deal.',
      refinanceReadiness: 'Insufficient Data',
      exitScore: 0,
      viability: 'Insufficient Data',
      strategies: [],
      comparison: [],
      stressTests: [],
      breakEvenThresholds: [],
      warnings: [],
      requiredActions: ['Add property valuation, debt payoff, and rent support data.'],
      summary: {
        message: 'Refinance & Exit analysis unavailable for this deal.',
      },
      refinanceAnalysis: {
        readyToRefinance: false,
        refinanceValue: 0,
        refinanceLoanAmount: 0,
        grossRefinanceProceeds: 0,
        netRefinanceProceeds: 0,
        cashReturned: 0,
        cashLeftInDeal: 0,
        capitalRecoveryPercentage: 0,
        newMonthlyPayment: 0,
        postRefinanceMonthlyCashFlow: 0,
        postRefinanceDscr: 0,
      },
      timeline: [],
      known: ['Insufficient property data was available for analysis.'],
      uncertain: ['The optimizer requires supported property and lender details to produce reliable exit guidance.'],
      needed: ['Property values', 'Loan payoff', 'Appraisal or ARV support', 'Rent and expenses'],
    });
  }
  const refinanceLtv = safeNumber(supportedProperty.refinanceLtv ?? supportedProperty.maxLtv ?? 0.75);
  const refinanceLoanAmount = value * refinanceLtv;
  const closingCosts = safeNumber(supportedProperty.refinanceClosingCosts ?? supportedProperty.closingCosts ?? value * 0.02);
  const reserves = safeNumber(supportedProperty.requiredReserves ?? supportedProperty.reserveRequirement ?? 0);
  const existingLoanPayoff = currentLoanBalance;
  const netRefinanceProceeds = refinanceLoanAmount - existingLoanPayoff - closingCosts - reserves;
  const cashReturned = Math.max(0, netRefinanceProceeds);
  const totalCashInvested = safeNumber(supportedProperty.totalCashInvested ?? supportedProperty.purchasePrice + supportedProperty.rehabBudget ?? supportedProperty.currentValue);
  const cashLeftInDeal = Math.max(0, totalCashInvested - cashReturned);
  const annualNoi = getAnnualNoi(supportedProperty);
  const newMonthlyPayment = monthlyDebtService;
  const postRefinanceMonthlyCashFlow = safeNumber(supportedProperty.monthlyRent ?? supportedProperty.effectiveRent) - safeNumber(supportedProperty.monthlyOperatingExpenses ?? supportedProperty.operatingExpenses) - newMonthlyPayment;
  const postRefinanceDscr = monthlyDebtService > 0 ? (annualNoi / (monthlyDebtService * 12)) : 0;
  const appraisalStatus = safeDisplay(supportedProperty.appraisalStatus ?? supportedProperty.appraisalComplete, 'Insufficient Data');
  const insuranceStatus = safeDisplay(supportedProperty.insuranceStatus ?? supportedProperty.insuranceCurrent, 'Insufficient Data');
  const titleStatus = safeDisplay(supportedProperty.titleStatus ?? supportedProperty.titleClear, 'Insufficient Data');
  const documentationCompleteness = safeNumber(supportedProperty.documentationCompleteness ?? 0);
  const loanMaturityDate = safeDisplay(supportedProperty.loanMaturityDate ?? supportedProperty.maturityDate, 'Insufficient Data');
  const occupancyRate = safeNumber(supportedProperty.occupancyRate ?? supportedProperty.leaseOccupancy ?? supportedProperty.currentOccupancy);
  const leaseStatus = safeDisplay(supportedProperty.leaseStatus ?? supportedProperty.tenantStatus, 'Insufficient Data');
  const rentReady = safeNumber(supportedProperty.monthlyRent ?? supportedProperty.effectiveRent) > 0 && occupancyRate >= 90;
  const hasAppraisal = safeNumber(supportedProperty.appraisedValue ?? supportedProperty.appraisalValue) > 0 || safeNumber(supportedProperty.supportedARV ?? supportedProperty.projectedARV) > 0;
  const hasLoanData = currentLoanBalance > 0 && safeNumber(supportedProperty.interestRate ?? supportedProperty.currentInterestRate) > 0;

  let refinanceReadiness = 'Insufficient Data';
  if (hasAppraisal && rentReady && hasLoanData && documentationCompleteness >= 0.8) {
    refinanceReadiness = 'Ready to Refinance';
  } else if (hasAppraisal && rentReady && hasLoanData) {
    refinanceReadiness = 'Ready with Conditions';
  } else if (rehabPercentComplete >= 60 && rehabRemainingBudget > 0) {
    refinanceReadiness = 'Refinance After Milestone';
  } else if (hasLoanData) {
    refinanceReadiness = 'Prepare to Refinance';
  } else {
    refinanceReadiness = 'Not Ready';
  }

  const refinanceStrategy = {
    strategy: 'Refinance and Hold',
    viability: cashReturned > 0 && refinanceReadiness === 'Ready to Refinance' ? 'Strong' : cashReturned > 0 && refinanceReadiness === 'Ready with Conditions' ? 'Viable' : refinanceReadiness === 'Refinance After Milestone' ? 'Conditional' : 'Marginal',
    estimatedValue: value,
    estimatedGrossProceeds: refinanceLoanAmount,
    estimatedNetProceeds: netRefinanceProceeds,
    capitalRequired: Math.max(0, reserves + closingCosts),
    capitalReturned: cashReturned,
    profit: netRefinanceProceeds - safeNumber(supportedProperty.remainingUnrecoveredCashInvestment ?? 0),
    roi: totalCashInvested > 0 ? (netRefinanceProceeds - totalCashInvested) / totalCashInvested : 0,
    annualizedRoi: totalCashInvested > 0 ? ((netRefinanceProceeds - totalCashInvested) / totalCashInvested) : 0,
    monthlyCashFlow: postRefinanceMonthlyCashFlow,
    annualCashFlow: postRefinanceMonthlyCashFlow * 12,
    dscr: postRefinanceDscr,
    cashLeftInDeal: cashLeftInDeal,
    timeToExit: '30-90 Days',
    liquidityImpact: cashReturned > 0 ? 'Positive' : 'Neutral',
    reserveImpact: reserves > 0 ? 'Moderate' : 'Low',
    riskLevel: refinanceReadiness === 'Ready to Refinance' ? 'Moderate' : 'Elevated',
    scenarioSurvival: 'Supported',
    dataConfidence: hasAppraisal && hasLoanData ? 'High' : 'Moderate',
    mainAdvantage: 'Releases capital while preserving the asset.',
    mainWeakness: 'Requires lender qualification and closing execution.',
    requiredConditions: 'Appraisal, payoff, and refinance term sheet.',
    requiredNextAction: 'Prepare refinance package and lender outreach.',
    exitScore: refinanceReadiness === 'Ready to Refinance' ? 90 : refinanceReadiness === 'Ready with Conditions' ? 78 : refinanceReadiness === 'Refinance After Milestone' ? 70 : 55,
    grade: refinanceReadiness === 'Ready to Refinance' ? 'A' : refinanceReadiness === 'Ready with Conditions' ? 'C' : refinanceReadiness === 'Refinance After Milestone' ? 'C' : 'F',
    explanation: 'Refinance is supported by current value and refinance capacity.',
  };

  const saleStrategy = {
    strategy: 'Sell After Rehab',
    viability: rehabRemainingBudget <= 0 && value > 0 ? 'Viable' : 'Conditional',
    estimatedValue: value,
    estimatedGrossProceeds: value,
    estimatedNetProceeds: value - safeNumber(supportedProperty.sellingCosts ?? value * 0.08) - currentLoanBalance - rehabRemainingBudget,
    capitalRequired: rehabRemainingBudget,
    capitalReturned: Math.max(0, value - currentLoanBalance - safeNumber(supportedProperty.sellingCosts ?? value * 0.08) - rehabRemainingBudget),
    profit: Math.max(0, value - currentLoanBalance - safeNumber(supportedProperty.sellingCosts ?? value * 0.08) - rehabRemainingBudget - totalCashInvested),
    roi: totalCashInvested > 0 ? (Math.max(0, value - currentLoanBalance - safeNumber(supportedProperty.sellingCosts ?? value * 0.08) - rehabRemainingBudget - totalCashInvested) / totalCashInvested) : 0,
    annualizedRoi: totalCashInvested > 0 ? (Math.max(0, value - currentLoanBalance - safeNumber(supportedProperty.sellingCosts ?? value * 0.08) - rehabRemainingBudget - totalCashInvested) / totalCashInvested) : 0,
    monthlyCashFlow: 0,
    annualCashFlow: 0,
    dscr: 0,
    cashLeftInDeal: Math.max(0, totalCashInvested - (value - currentLoanBalance - safeNumber(supportedProperty.sellingCosts ?? value * 0.08) - rehabRemainingBudget)),
    timeToExit: rehabRemainingBudget > 0 ? '90-180 Days' : '30-90 Days',
    liquidityImpact: 'High',
    reserveImpact: 'Moderate',
    riskLevel: rehabRemainingBudget > 0 ? 'Elevated' : 'Moderate',
    scenarioSurvival: 'Supported',
    dataConfidence: value > 0 ? 'Moderate' : 'Insufficient Data',
    mainAdvantage: 'Provides clean liquidity and exits the asset.',
    mainWeakness: 'Requires sale execution and market timing.',
    requiredConditions: 'Listing estimate and payoff statement.',
    requiredNextAction: 'Prepare sale marketing and payoff review.',
    exitScore: rehabRemainingBudget <= 0 ? 74 : 63,
    grade: rehabRemainingBudget <= 0 ? 'C' : 'D',
    explanation: 'Sale becomes more attractive when rehab and carrying costs are controlled.',
  };

  const holdStrategy = {
    strategy: 'Hold Existing Financing',
    viability: postRefinanceDscr >= 1.2 ? 'Viable' : 'Conditional',
    estimatedValue: value,
    estimatedGrossProceeds: 0,
    estimatedNetProceeds: 0,
    capitalRequired: 0,
    capitalReturned: 0,
    profit: 0,
    roi: 0,
    annualizedRoi: 0,
    monthlyCashFlow: safeNumber(supportedProperty.monthlyRent ?? supportedProperty.effectiveRent) - safeNumber(supportedProperty.monthlyOperatingExpenses ?? supportedProperty.operatingExpenses) - monthlyDebtService,
    annualCashFlow: (safeNumber(supportedProperty.monthlyRent ?? supportedProperty.effectiveRent) - safeNumber(supportedProperty.monthlyOperatingExpenses ?? supportedProperty.operatingExpenses) - monthlyDebtService) * 12,
    dscr: postRefinanceDscr,
    cashLeftInDeal: totalCashInvested,
    timeToExit: 'Longer-Term',
    liquidityImpact: 'Neutral',
    reserveImpact: 'Low',
    riskLevel: 'Moderate',
    scenarioSurvival: 'Conditional',
    dataConfidence: safeNumber(supportedProperty.monthlyRent ?? supportedProperty.effectiveRent) > 0 ? 'Moderate' : 'Insufficient Data',
    mainAdvantage: 'Preserves optionality while generating cash flow.',
    mainWeakness: 'Requires time and ongoing carrying cost.',
    requiredConditions: 'Stabilized rent and active operating review.',
    requiredNextAction: 'Reassess cash flow and maturity timing.',
    exitScore: postRefinanceDscr >= 1.2 ? 69 : 54,
    grade: postRefinanceDscr >= 1.2 ? 'D' : 'F',
    explanation: 'Holding remains viable when cash flow and debt service are stable.',
  };

  const comparison = [buildStrategy(refinanceStrategy), buildStrategy(saleStrategy), buildStrategy(holdStrategy)]
    .sort((a, b) => safeNumber(b.exitScore) - safeNumber(a.exitScore));

  const primaryExit = comparison[0]?.strategy || 'Insufficient Data';
  const secondaryExit = comparison[1]?.strategy || 'Insufficient Data';
  const exitToAvoid = comparison[comparison.length - 1]?.strategy || 'Insufficient Data';
  const decisionStatus = refinanceStrategy.exitScore >= 80 ? 'Execute with Conditions' : refinanceStrategy.exitScore >= 70 ? 'Prepare Now' : 'Re-Underwrite';
  const known = [
    `Supported value is ${formatCurrency(value)}`,
    `Current loan balance is ${formatCurrency(currentLoanBalance)}`,
    `Rehab remaining budget is ${formatCurrency(rehabRemainingBudget)}`,
  ];
  const uncertain = [
    'The refinance value depends on appraisal and lender qualification.',
    'Sale proceeds depend on market timing and carrying costs.',
    'Hold performance depends on verified rent and occupancy.',
  ];
  const needed = [
    'Appraisal',
    'Payoff statement',
    'Refinance term sheet',
    'Verified rent',
    'Updated insurance',
    'Updated taxes',
    'Listing estimate',
    'Remaining rehab scope',
  ];

  const breakEvenThresholds = [
    {
      metric: 'Refinance remains viable only if value is at least',
      threshold: formatCurrency(currentLoanBalance / refinanceLtv || 0),
    },
    {
      metric: 'Sale remains viable only if price is at least',
      threshold: formatCurrency(currentLoanBalance + rehabRemainingBudget + safeNumber(supportedProperty.sellingCosts ?? value * 0.08) + totalCashInvested * 0.1),
    },
    {
      metric: 'Hold remains viable only if rent is at least',
      threshold: formatCurrency((safeNumber(supportedProperty.monthlyOperatingExpenses ?? supportedProperty.operatingExpenses) + monthlyDebtService) / 1),
    },
    {
      metric: 'Rehab must remain below',
      threshold: formatCurrency(value * 0.2),
    },
  ];

  const stressTests = [
    {
      scenario: 'Sale Stress - 10%',
      viability: 'Conditional',
      profit: formatCurrency(saleStrategy.profit * 0.9),
      roi: formatPercent(saleStrategy.roi * 0.9),
      cashReturned: formatCurrency(saleStrategy.capitalReturned * 0.9),
      cashLeftInDeal: formatCurrency(saleStrategy.cashLeftInDeal * 1.05),
      cashFlow: formatCurrency(0),
      dscr: 'Insufficient Data',
      liquidityImpact: 'Moderate',
      exitScore: 66,
      recommendation: 'Reassess sale timing',
    },
    {
      scenario: 'Refinance Stress - 10%',
      viability: 'Conditional',
      profit: formatCurrency(refinanceStrategy.profit * 0.9),
      roi: formatPercent(refinanceStrategy.roi * 0.9),
      cashReturned: formatCurrency(refinanceStrategy.capitalReturned * 0.9),
      cashLeftInDeal: formatCurrency(refinanceStrategy.cashLeftInDeal * 1.05),
      cashFlow: formatCurrency(postRefinanceMonthlyCashFlow * 0.95),
      dscr: `${(postRefinanceDscr * 0.95).toFixed(2)}x`,
      liquidityImpact: 'Moderate',
      exitScore: 72,
      recommendation: 'Preserve reserves and confirm lender terms',
    },
    {
      scenario: 'Hold Stress - 10%',
      viability: 'Conditional',
      profit: formatCurrency(0),
      roi: formatPercent(0),
      cashReturned: formatCurrency(0),
      cashLeftInDeal: formatCurrency(totalCashInvested),
      cashFlow: formatCurrency(holdStrategy.monthlyCashFlow * 0.9),
      dscr: `${(postRefinanceDscr * 0.9).toFixed(2)}x`,
      liquidityImpact: 'Neutral',
      exitScore: 57,
      recommendation: 'Re-underwrite hold assumptions',
    },
  ];

  return buildSafeOptimizerResult({
    status: 'Ready',
    primaryExit,
    secondaryExit,
    exitToAvoid,
    recommendedTiming: refinanceReadiness === 'Ready to Refinance' ? 'Refinance Now' : rehabPercentComplete >= 60 ? 'Refinance After Rehab Completion' : 'Prepare Now',
    decisionStatus,
    reason: refinanceStrategy.exitScore >= 80 ? 'Supported refinance economics and acceptable risk support an immediate exit path.' : 'The exit path is viable but requires more data or conditions before proceeding.',
    refinanceReadiness,
    exitScore: refinanceStrategy.exitScore,
    viability: refinanceStrategy.viability,
    strategies: comparison,
    comparison,
    warnings: [],
    requiredActions: ['Collect payoff and lender terms', 'Confirm appraisal and rent support', 'Review hold assumptions'],
    refinanceAnalysis: {
      readyToRefinance: refinanceReadiness === 'Ready to Refinance',
      refinanceValue: value,
      refinanceLoanAmount,
      grossRefinanceProceeds: refinanceLoanAmount,
      netRefinanceProceeds,
      cashReturned,
      cashLeftInDeal,
      capitalRecoveryPercentage: totalCashInvested > 0 ? (cashReturned / totalCashInvested) * 100 : 0,
      newMonthlyPayment,
      postRefinanceMonthlyCashFlow,
      postRefinanceDscr,
    },
    breakEvenThresholds,
    stressTests,
    timeline: [
      {
        property: supportedProperty.propertyName || 'Unnamed Property',
        currentStage: 'Current',
        requiredMilestone: 'Appraisal and payoff',
        targetExit: primaryExit,
        targetDate: loanMaturityDate,
        loanMaturity: loanMaturityDate,
        daysAvailable: 'Insufficient Data',
        risk: refinanceReadiness === 'Ready to Refinance' ? 'Moderate' : 'Elevated',
        requiredAction: 'Collect payoff and lender terms',
      },
    ],
    known,
    uncertain,
    needed,
    capitalIntegration: {
      capitalRequired: safeNumber(refinanceStrategy.capitalRequired) + safeNumber(saleStrategy.capitalRequired),
      capitalReturned: safeNumber(refinanceStrategy.capitalReturned) + safeNumber(saleStrategy.capitalReturned),
      liquidityImpact: refinanceStrategy.capitalReturned > saleStrategy.capitalReturned ? 'Refinance' : 'Sale',
    },
    summary: {
      message: 'Refinance & Exit analysis completed for this deal.',
      estimatedCapitalReleased: formatCurrency(refinanceStrategy.capitalReturned + saleStrategy.capitalReturned),
      estimatedCapitalRequired: formatCurrency(refinanceStrategy.capitalRequired + saleStrategy.capitalRequired),
      exitScore: refinanceStrategy.exitScore,
    },
    portfolioSummary: {
      refinanceNowProperties: properties.filter((property) => property.refinanceCandidate).length,
      prepareToRefinanceProperties: properties.filter((property) => safeNumber(property.rehabPercentComplete ?? property.percentComplete) >= 60).length,
      sellNowCandidates: properties.filter((property) => safeNumber(property.currentValue ?? property.value) > 0 && safeNumber(property.currentLoanBalance ?? property.loanBalance) > 0).length,
      holdCandidates: properties.filter((property) => safeNumber(property.monthlyRent ?? property.effectiveRent) > 0).length,
      estimatedCapitalReleased: formatCurrency(refinanceStrategy.capitalReturned + saleStrategy.capitalReturned),
      estimatedCapitalRequired: formatCurrency(refinanceStrategy.capitalRequired + saleStrategy.capitalRequired),
    },
  });
}

